{
  "name": "agent-hq",
  "version": "2.0.0",
  "private": true,
  "description": "AGENT HQ — real research operations for DEEMANNIE'S DIGITAL",
  "type": "module",
  "engines": {
    "node": ">=20.11"
  },
  "scripts": {
    "start": "node server/index.js",
    "dev": "node --watch server/index.js",
    "test": "node --test test/",
    "build": "node scripts/build.js",
    "check": "node scripts/check.js"
  }
}

/**
 * Error types shared by the execution bridge, HTTP client and API layer.
 * Public errors are deliberately boring: they never include credentials,
 * request headers, or raw provider payloads.
 */
export class AppError extends Error {
  constructor(code, message, options = {}) {
    super(message, options.cause ? { cause: options.cause } : undefined);
    this.name = 'AppError';
    this.code = code;
    this.status = options.status ?? 500;
    this.recoverable = options.recoverable ?? false;
    this.detail = options.detail ?? null;
  }
}

export class ValidationError extends AppError {
  constructor(message, detail = null) {
    super('VALIDATION_FAILED', message, { status: 400, recoverable: true, detail });
    this.name = 'ValidationError';
  }
}

export class ExecutionError extends AppError {
  constructor(code, message, options = {}) {
    super(code, message, {
      status: options.status ?? 502,
      recoverable: options.recoverable ?? true,
      detail: options.detail ?? null,
      cause: options.cause
    });
    this.name = 'ExecutionError';
  }
}

export function toPublicError(error) {
  if (error instanceof AppError) {
    return {
      code: error.code,
      message: error.message,
      recoverable: Boolean(error.recoverable),
      ...(error.detail ? { detail: error.detail } : {})
    };
  }
  return {
    code: 'INTERNAL_ERROR',
    message: 'An unexpected error interrupted the operation.',
    recoverable: true
  };
}

export function statusForError(error) {
  return error instanceof AppError ? error.status : 500;
}

import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
export const ROOT_DIR = path.resolve(here, '..');

export function readConfig(overrides = {}) {
  return {
    port: Number(process.env.PORT ?? 3000),
    host: process.env.HOST ?? '0.0.0.0',
    dataDir: path.resolve(process.env.DATA_DIR ?? path.join(ROOT_DIR, '..', 'data')),
    publicDir: path.resolve(process.env.PUBLIC_DIR ?? path.join(ROOT_DIR, '..', 'public')),
    seedPath:
      process.env.SEED_STATE === 'off'
        ? null
        : path.resolve(process.env.SEED_STATE ?? path.join(ROOT_DIR, '..', 'data', 'seed-state.json')),
    version: '2.0.0',
    userAgent:
      process.env.RESEARCH_USER_AGENT ??
      'DEEMANNIES-AGENT-HQ/2.0 (local research; https://github.com/dannyleonards42-web/PlayGround)',
    ...overrides
  };
}

const LEVELS = { debug: 10, info: 20, warn: 30, error: 40 };

function write(level, event, fields = {}) {
  if ((LEVELS[level] ?? 20) < (LEVELS[process.env.LOG_LEVEL] ?? 20)) return;
  const line = JSON.stringify({
    at: new Date().toISOString(),
    level,
    event,
    ...fields
  });
  if (level === 'error') console.error(line);
  else console.log(line);
}

export const log = {
  debug: (event, fields) => write('debug', event, fields),
  info: (event, fields) => write('info', event, fields),
  warn: (event, fields) => write('warn', event, fields),
  error: (event, fields) => write('error', event, fields)
};

import { randomBytes } from 'node:crypto';

export function newId(prefix) {
  return `${prefix}_${randomBytes(6).toString('hex')}`;
}

export function nowIso() {
  return new Date().toISOString();
}

export function trimTo(value, max) {
  if (typeof value !== 'string') return '';
  return value.replace(/\s+/g, ' ').trim().slice(0, max);
}

export function slugify(value) {
  return String(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 60) || 'untitled';
}

import { lookup } from 'node:dns/promises';
import net from 'node:net';
import { AppError } from './errors.js';

const BLOCKED_HOST_SUFFIXES = ['.local', '.internal', '.localhost', '.home.arpa'];
const BLOCKED_HOSTS = new Set([
  'localhost',
  'localhost.localdomain',
  'metadata',
  'metadata.google.internal',
  'metadata.azure.internal',
  'instance-data'
]);

function ipv4IsPrivate(ip) {
  const parts = ip.split('.').map(Number);
  if (parts.length !== 4 || parts.some((n) => !Number.isInteger(n) || n < 0 || n > 255)) return true;
  const [a, b] = parts;
  if (a === 0 || a === 10 || a === 127) return true;
  if (a === 100 && b >= 64 && b <= 127) return true;
  if (a === 169 && b === 254) return true;
  if (a === 172 && b >= 16 && b <= 31) return true;
  if (a === 192 && b === 168) return true;
  if (a === 192 && b === 0 && (parts[2] === 0 || parts[2] === 2)) return true;
  if (a === 192 && b === 88 && parts[2] === 99) return true;
  if (a === 198 && (b === 18 || b === 19)) return true;
  if (a === 198 && b === 51 && parts[2] === 100) return true;
  if (a === 203 && b === 0 && parts[2] === 113) return true;
  if (a >= 224) return true;
  return false;
}

export function isPrivateIp(input) {
  if (typeof input !== 'string') return true;
  const ip = input.trim().toLowerCase().replace(/^\[|\]$/g, '').split('%')[0];
  const version = net.isIP(ip);
  if (version === 4) return ipv4IsPrivate(ip);
  if (version !== 6) return true;

  if (ip === '::1' || ip === '::') return true;
  if (ip.startsWith('fe8') || ip.startsWith('fe9') || ip.startsWith('fea') || ip.startsWith('feb')) return true;
  if (ip.startsWith('fc') || ip.startsWith('fd')) return true;
  if (ip.startsWith('ff')) return true;
  if (ip.startsWith('2001:db8')) return true;
  if (ip.startsWith('fec')) return true;

  const mapped = ip.match(/^::ffff:(\d+\.\d+\.\d+\.\d+)$/);
  if (mapped) return ipv4IsPrivate(mapped[1]);

  return false;
}

export function assertSafeUrl(rawUrl) {
  let url;
  try {
    url = new URL(rawUrl);
  } catch {
    throw new AppError('INVALID_URL', 'The website URL is not valid.', { status: 400, recoverable: true });
  }
  if (!['http:', 'https:'].includes(url.protocol)) {
    throw new AppError('UNSAFE_URL', 'Only public http and https websites may be inspected.', {
      status: 400,
      recoverable: true
    });
  }
  if (url.username || url.password) {
    throw new AppError('UNSAFE_URL', 'Website URLs containing credentials are not allowed.', {
      status: 400,
      recoverable: true
    });
  }
  if (!['80', '443'].includes(url.port) && url.port !== '') {
    throw new AppError('UNSAFE_URL', 'Only standard web ports may be inspected.', {
      status: 400,
      recoverable: true
    });
  }
  const host = url.hostname.toLowerCase().replace(/\.$/, '');
  if (!host || BLOCKED_HOSTS.has(host) || BLOCKED_HOST_SUFFIXES.some((suffix) => host.endsWith(suffix))) {
    throw new AppError('UNSAFE_URL', 'Local and private network addresses cannot be inspected.', {
      status: 400,
      recoverable: true
    });
  }
  if (net.isIP(host)) {
    if (isPrivateIp(host)) {
      throw new AppError('UNSAFE_URL', 'Local and private network addresses cannot be inspected.', {
        status: 400,
        recoverable: true
      });
    }
    return url;
  }
  return url;
}

export async function assertPublicHost(url, resolver = lookup) {
  const safeUrl = assertSafeUrl(url.href);
  let addresses;
  try {
    addresses = await resolver(safeUrl.hostname, { all: true, verbatim: true });
  } catch (error) {
    throw new AppError('DNS_FAILED', `Could not resolve ${safeUrl.hostname}.`, {
      status: 502,
      recoverable: true,
      cause: error
    });
  }
  if (!addresses.length) {
    throw new AppError('DNS_FAILED', `No addresses were returned for ${safeUrl.hostname}.`, {
      status: 502,
      recoverable: true
    });
  }
  if (addresses.some((entry) => isPrivateIp(entry.address))) {
    throw new AppError('UNSAFE_URL', 'This hostname resolves to a private network address.', {
      status: 400,
      recoverable: true
    });
  }
  return safeUrl;
}

import { AppError } from './errors.js';
import { assertPublicHost } from './network-guard.js';

const DEFAULT_MAX_BYTES = 2_500_000;
const DEFAULT_TIMEOUT_MS = 12_000;

function decodeBody(buffer, contentType) {
  const charset = /charset\s*=\s*["']?([\w-]+)/i.exec(contentType ?? '')?.[1]?.toLowerCase();
  const decoder = charset
    ? (() => {
        try {
          return new TextDecoder(charset);
        } catch {
          return new TextDecoder('utf-8');
        }
      })()
    : new TextDecoder('utf-8');
  return decoder.decode(buffer);
}

async function readCapped(response, maxBytes) {
  const declared = Number(response.headers.get('content-length') ?? 0);
  if (declared > maxBytes) {
    throw new AppError('RESPONSE_TOO_LARGE', 'The website response exceeded the inspection size limit.', {
      status: 502,
      recoverable: true
    });
  }
  if (!response.body) return new Uint8Array();
  const reader = response.body.getReader();
  const chunks = [];
  let total = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      total += value.byteLength;
      if (total > maxBytes) {
        await reader.cancel().catch(() => {});
        throw new AppError('RESPONSE_TOO_LARGE', 'The website response exceeded the inspection size limit.', {
          status: 502,
          recoverable: true
        });
      }
      chunks.push(value);
    }
  } finally {
    reader.releaseLock?.();
  }
  const body = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    body.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return body;
}

/**
 * Fetch a public web page with redirect re-validation, a body cap and timeouts.
 * Returns the final response even when the status is 4xx/5xx so the audit can
 * report exactly what a real visitor would see.
 */
export async function safeFetch(rawUrl, options = {}) {
  const {
    fetchImpl = globalThis.fetch,
    userAgent = 'DEEMANNIES-AGENT-HQ/2.0 (local research)',
    maxBytes = DEFAULT_MAX_BYTES,
    timeoutMs = DEFAULT_TIMEOUT_MS,
    maxRedirects = 3,
    resolver
  } = options;

  let current = new URL(rawUrl);
  const started = performance.now();
  const chain = [];

  for (let redirects = 0; ; redirects += 1) {
    await assertPublicHost(current, resolver);
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    let response;
    try {
      response = await fetchImpl(current, {
        method: 'GET',
        redirect: 'manual',
        credentials: 'omit',
        signal: controller.signal,
        headers: {
          'user-agent': userAgent,
          accept: 'text/html,application/xhtml+xml;q=0.9,*/*;q=0.5',
          'accept-language': 'en-US,en;q=0.8'
        }
      });
    } catch (error) {
      const timedOut = error?.name === 'AbortError';
      throw new AppError(
        timedOut ? 'FETCH_TIMEOUT' : 'FETCH_FAILED',
        timedOut
          ? `The website did not respond within ${Math.round(timeoutMs / 1000)} seconds.`
          : `Could not reach ${current.hostname}.`,
        { status: 502, recoverable: true, cause: error }
      );
    } finally {
      clearTimeout(timer);
    }

    const location = response.headers.get('location');
    if (response.status >= 300 && response.status < 400 && location) {
      if (redirects >= maxRedirects) {
        throw new AppError('TOO_MANY_REDIRECTS', 'The website redirected too many times.', {
          status: 502,
          recoverable: true
        });
      }
      chain.push(current.href);
      current = new URL(location, current);
      continue;
    }

    const bytes = await readCapped(response, maxBytes);
    const headers = Object.fromEntries(response.headers.entries());
    const contentType = headers['content-type'] ?? '';
    return {
      requestedUrl: rawUrl,
      finalUrl: current.href,
      redirects: chain,
      status: response.status,
      headers,
      contentType,
      body: decodeBody(bytes, contentType),
      bytes: bytes.byteLength,
      elapsedMs: Math.round(performance.now() - started),
      fetchedAt: new Date().toISOString()
    };
  }
}

const ENTITY_MAP = {
  amp: '&',
  lt: '<',
  gt: '>',
  quot: '"',
  apos: "'",
  nbsp: ' '
};

export function decodeEntities(value = '') {
  return String(value)
    .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCodePoint(parseInt(code, 16)))
    .replace(/&([a-z]+);/gi, (match, name) => ENTITY_MAP[name.toLowerCase()] ?? match);
}

export function stripTags(html = '') {
  return decodeEntities(
    html
      .replace(/<script\b[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style\b[\s\S]*?<\/style>/gi, ' ')
      .replace(/<noscript\b[\s\S]*?<\/noscript>/gi, ' ')
      .replace(/<[^>]+>/g, ' ')
  )
    .replace(/\s+/g, ' ')
    .trim();
}

export function parseAttributes(tag) {
  const attrs = {};
  const body = tag.replace(/^<\s*[\w:-]+/, '').replace(/\/?>$/, '');
  const re = /([\w:.-]+)\s*=\s*("([^"]*)"|'([^']*)'|([^\s"'>]+))/g;
  let match;
  while ((match = re.exec(body))) {
    attrs[match[1].toLowerCase()] = decodeEntities(match[3] ?? match[4] ?? match[5] ?? '');
  }
  return attrs;
}

function metaTags(html) {
  return [...html.matchAll(/<meta\b[^>]*>/gi)].map((match) => parseAttributes(match[0]));
}

export function analyzeHtml(html, headers = {}) {
  const titleMatch = /<title\b[^>]*>([\s\S]*?)<\/title>/i.exec(html);
  const title = titleMatch ? decodeEntities(titleMatch[1]).replace(/\s+/g, ' ').trim() : '';
  const metas = metaTags(html);
  const metaByName = (name) =>
    metas.find((meta) => (meta.name ?? '').toLowerCase() === name)?.content ??
    metas.find((meta) => (meta.property ?? '').toLowerCase() === name)?.content ??
    '';
  const canonical = [...html.matchAll(/<link\b[^>]*>/gi)]
    .map((match) => parseAttributes(match[0]))
    .find((attrs) => (attrs.rel ?? '').toLowerCase() === 'canonical')?.href;

  const links = [...html.matchAll(/<a\b[^>]*>([\s\S]*?)<\/a>/gi)].map((match) => ({
    attrs: parseAttributes(match[0].slice(0, match[0].indexOf('>') + 1)),
    text: stripTags(match[1])
  }));
  const hrefs = links.map((link) => link.attrs.href ?? '').filter(Boolean);
  const allHrefs = hrefs.join(' ');
  const text = stripTags(html);

  const generator =
    metaByName('generator') ||
    (/squarespace/i.test(html) ? 'Squarespace' : '') ||
    (/cdn\.shopify|shopify\.com/i.test(html) ? 'Shopify' : '') ||
    (/wp-content|wordpress/i.test(html) ? 'WordPress' : '') ||
    (/wixstatic|wix\.com/i.test(html) ? 'Wix' : '') ||
    (/webflow/i.test(html) ? 'Webflow' : '');

  const social = [];
  if (/instagram\.com/i.test(allHrefs)) social.push('Instagram');
  if (/facebook\.com/i.test(allHrefs)) social.push('Facebook');
  if (/linkedin\.com/i.test(allHrefs)) social.push('LinkedIn');
  if (/tiktok\.com/i.test(allHrefs)) social.push('TikTok');
  if (/youtube\.com|youtu\.be/i.test(allHrefs)) social.push('YouTube');
  if (/x\.com|twitter\.com/i.test(allHrefs)) social.push('X / Twitter');

  const formBlocks = [...html.matchAll(/<form\b[\s\S]*?<\/form>/gi)].map((match) => match[0]);
  const hasForm = formBlocks.length > 0;
  const hasContactForm = formBlocks.some(
    (form) =>
      /type\s*=\s*["']?email/i.test(form) ||
      /name\s*=\s*["']?(name|email|message|comments|contact)/i.test(form) ||
      /(contact|enquir|inquir)/i.test(form)
  );

  const orderingPattern =
    /order\s+(online|now|for pickup)|add\s+to\s+cart|shop\s+now|buy\s+now|book\s+(a\s+)?(table|now)|reserve|reservation|start\s+order/i;
  const ordering = orderingPattern.test(text) || orderingPattern.test(allHrefs);
  const menuLink = links.some(
    (link) => /menu/i.test(link.text) || /\/menu|menu\./i.test(link.attrs.href ?? '')
  );

  const copyrightYears = [...text.matchAll(/(?:©|copyright|&copy;)[^0-9]{0,30}(20\d{2})/gi)]
    .map((match) => Number(match[1]))
    .filter((year) => year >= 2000 && year <= 2100);
  const copyrightYear = copyrightYears.length ? Math.max(...copyrightYears) : null;

  const jsonLdTypes = [];
  for (const match of html.matchAll(/<script[^>]+application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
    for (const type of match[1].matchAll(/"@type"\s*:\s*"([^"]+)"/g)) jsonLdTypes.push(type[1]);
  }

  const phone = hrefs.some((href) => /^tel:/i.test(href));
  const email = hrefs.some((href) => /^mailto:/i.test(href));
  const addressInText = /(?:street|st\.|avenue|ave\.|boulevard|blvd|road|rd\.|drive|dr\.)\b/i.test(text);
  const viewport = metas.some((meta) => (meta.name ?? '').toLowerCase() === 'viewport');
  const description = metaByName('description');
  const hsts = /max-age\s*=\s*([1-9]\d*)/i.test(headers['strict-transport-security'] ?? '');
  const analytics =
    /googletagmanager|google-analytics|gtag\(|plausible\.io|usefathom|clarity\.ms|matomo|segment\.com/i.test(html);

  return {
    title,
    description,
    descriptionLength: description.length,
    canonical: canonical ?? null,
    viewport,
    generator: generator || null,
    social: [...new Set(social)],
    hasForm,
    hasContactForm,
    phone,
    email,
    ordering,
    menuLink,
    copyrightYear,
    jsonLdTypes: [...new Set(jsonLdTypes)],
    hasLocalBusinessSchema: jsonLdTypes.some((type) => /localbusiness|bakery|restaurant|cafe|store|foodestablishment/i.test(type)),
    hsts,
    analytics,
    addressInText,
    text,
    hrefs
  };
}

import { analyzeHtml } from './html-analyzer.js';

const STOP_WORDS = new Set([
  'the', 'and', 'of', 'portland', 'oregon', 'bakery', 'bakeries', 'cafe', 'café',
  'restaurant', 'coffee', 'shop', 'store', 'company', 'inc', 'llc', 'bistro'
]);

function nameTokens(name) {
  return String(name)
    .toLowerCase()
    .split(/[^a-z0-9é]+/i)
    .filter((token) => token.length >= 4 && !STOP_WORDS.has(token));
}

function looksBlocked(page, analysis) {
  if (!page) return false;
  if ([401, 403, 429, 503].includes(page.status)) return true;
  return /just a moment|access denied|blocked by (our|the) firewall|attention required|challenge/i.test(
    `${analysis?.title ?? ''} ${analysis?.text?.slice(0, 600) ?? ''}`
  );
}

function sourceFor(business, url, label = null) {
  return {
    label: label ?? `${business.name} homepage`,
    url,
    type: 'website'
  };
}

/**
 * Turn a raw webpage response into verified observations and clearly-labelled
 * assumptions. No traffic, revenue, ranking or intent data is inferred.
 */
export function auditWebsite(business, page, { now, factPrefix = 'fact' } = {}) {
  const checkedAt = page?.fetchedAt ?? now ?? new Date().toISOString();
  const websiteUrl = page?.requestedUrl ?? business.websiteUrl ?? null;
  const facts = [];
  const assumptions = [];
  const signals = [];
  let counter = 0;
  let signalCounter = 0;

  const fact = (statement, { url = page?.finalUrl ?? websiteUrl, label, method } = {}) => {
    counter += 1;
    const entry = {
      id: `${factPrefix}_f${counter}`,
      type: 'verified',
      statement,
      source: sourceFor(business, url, label),
      observedAt: checkedAt,
      method: method ?? 'Direct HTTP GET; static HTML inspection (JavaScript not executed)'
    };
    facts.push(entry);
    return entry;
  };

  const signal = (label, weight, factEntry, recommendation, severity) => {
    signalCounter += 1;
    signals.push({
      id: `${factPrefix}_s${signalCounter}`,
      label,
      weight,
      severity,
      factId: factEntry.id,
      recommendation
    });
  };

  if (!page || page.error) {
    const message = page?.error?.message ?? 'The website could not be reached.';
    const failure = fact(`Homepage could not be reached: ${message}`, {
      url: websiteUrl,
      method: 'Attempted direct HTTP GET with redirect and SSRF validation'
    });
    signal('Website unavailable for automated inspection', 0, failure, 'Perform a manual browser review before outreach.', 2);
    assumptions.push({
      id: `${factPrefix}_a1`,
      type: 'assumption',
      statement: 'There may be a website opportunity, but it cannot be assessed until the site is reachable.',
      rationale: 'The audit stopped at the network layer. No conclusion about design, content or conversion is made.',
      basis: [failure.id],
      confidence: 'low'
    });
    return {
      verified: false,
      state: 'UNREACHABLE',
      website: {
        url: websiteUrl,
        finalUrl: null,
        status: null,
        verified: false,
        title: null,
        generator: null,
        bytes: null,
        elapsedMs: null,
        checkedAt,
        identityMatch: false,
        locationMatch: false,
        limitation: message
      },
      facts,
      assumptions,
      opportunitySignals: signals,
      score: 0,
      priority: 'REVIEW',
      opportunity: {
        headline: 'Website could not be reached',
        summary: 'No claims are made about this site. NOVA recorded the failure and recommends a manual browser check.',
        signals
      },
      checks: null
    };
  }

  const analysis = page.status === 200 ? analyzeHtml(page.body, page.headers) : null;
  const blocked = looksBlocked(page, analysis);
  const isHtml = /html/i.test(page.contentType ?? '');
  const verified = page.status === 200 && isHtml;

  const responseFact = fact(
    `Homepage responded HTTP ${page.status}${page.redirects?.length ? ` after ${page.redirects.length} redirect(s)` : ''} at ${page.finalUrl}.`,
    { url: page.finalUrl, method: 'Direct HTTP GET with redirect and SSRF validation' }
  );

  if (!verified) {
    const reason = blocked
      ? 'The website served a firewall or bot-challenge page, so its content could not be inspected.'
      : `The website returned ${page.contentType || 'a non-HTML response'}, so no site-quality conclusions are made.`;
    signal('Automated site audit blocked', 0, responseFact, 'Use a manual browser review; do not infer site quality from the block.', 2);
    assumptions.push({
      id: `${factPrefix}_a1`,
      type: 'assumption',
      statement: 'A website opportunity may exist, but it requires a manual review to assess.',
      rationale: blocked
        ? 'The delivered page was a firewall challenge rather than the business homepage.'
        : 'The response was not inspectable HTML.',
      basis: [responseFact.id],
      confidence: 'low'
    });
    return {
      verified: false,
      state: blocked ? 'BLOCKED' : 'NOT_HTML',
      website: {
        url: websiteUrl,
        finalUrl: page.finalUrl,
        status: page.status,
        verified: false,
        title: analysis?.title || null,
        generator: null,
        bytes: page.bytes,
        elapsedMs: page.elapsedMs,
        checkedAt,
        identityMatch: false,
        locationMatch: false,
        limitation: reason
      },
      facts,
      assumptions,
      opportunitySignals: signals,
      score: 0,
      priority: 'REVIEW',
      opportunity: {
        headline: 'Manual review required',
        summary: reason,
        signals
      },
      checks: null
    };
  }

  const tokens = nameTokens(business.name);
  const titleLower = analysis.title.toLowerCase();
  const identityMatch =
    tokens.some((token) => titleLower.includes(token)) ||
    titleLower.includes(String(business.name).toLowerCase());
  const cityToken = String(business.city ?? '').split(',')[0].trim().toLowerCase();
  const locationMatch = cityToken.length > 2 && analysis.text.toLowerCase().includes(cityToken);
  const titleFact = fact(`Homepage title: “${analysis.title || '(no title)'}”.`);
  const identityFact = fact(
    identityMatch
      ? `The homepage title contains a distinctive token from the source business name “${business.name}”.`
      : `The homepage title does not clearly match the source business name “${business.name}”.`
  );
  const descriptionFact = fact(
    analysis.description
      ? `Meta description present (${analysis.descriptionLength} characters): “${analysis.description.slice(0, 180)}”.`
      : 'No meta description is present in the delivered HTML.'
  );
  const viewportFact = fact(
    analysis.viewport
      ? 'A viewport meta tag is present, declaring a responsive layout.'
      : 'No viewport meta tag is present in the delivered HTML.'
  );
  const weightFact = fact(
    `Homepage HTML payload is ${Math.round(page.bytes / 1024)} KB and responded in ${page.elapsedMs} ms.`
  );
  const platformFact = fact(
    analysis.generator
      ? `Detected publishing platform: ${analysis.generator}.`
      : 'No common publishing platform signature was detected.'
  );
  const contactFact = fact(
    [
      analysis.email ? 'email link' : null,
      analysis.phone ? 'phone link' : null,
      analysis.hasContactForm ? 'contact form' : null,
      analysis.hasForm && !analysis.hasContactForm ? 'non-contact form' : null
    ].filter(Boolean).length
      ? `Visible contact actions detected: ${[
          analysis.email ? 'email link' : null,
          analysis.phone ? 'phone link' : null,
          analysis.hasContactForm ? 'contact form' : null,
          analysis.hasForm && !analysis.hasContactForm ? 'non-contact form' : null
        ].filter(Boolean).join(', ')}.`
      : 'No email link, phone link, or contact form was detected in the delivered HTML.'
  );
  const orderFact = fact(
    analysis.ordering
      ? 'An online ordering, shopping, or reservation call to action is present.'
      : 'No online ordering, shopping, or reservation call to action was detected in the delivered HTML.'
  );
  const menuFact = fact(
    analysis.menuLink
      ? 'A menu link is present in the homepage navigation or calls to action.'
      : 'No menu link was detected in the delivered HTML.'
  );
  const socialFact = fact(
    analysis.social.length
      ? `Social profile links detected: ${analysis.social.join(', ')}.`
      : 'No social profile links were detected in the delivered HTML.'
  );
  const schemaFact = fact(
    analysis.hasLocalBusinessSchema
      ? `Local-business structured data present (${analysis.jsonLdTypes.join(', ')}).`
      : 'No LocalBusiness-style structured data was detected in the delivered HTML.'
  );
  const hstsFact = fact(
    analysis.hsts
      ? 'Strict-Transport-Security is present with a positive max-age.'
      : 'No positive Strict-Transport-Security max-age header was observed.'
  );
  if (analysis.copyrightYear) {
    fact(`The homepage displays a ${analysis.copyrightYear} copyright year.`);
  }
  fact(
    analysis.analytics
      ? 'A web analytics or tag-manager signature is present.'
      : 'No common analytics or tag-manager signature was detected.'
  );

  if (!identityMatch) {
    signal('Homepage identity is unclear', 10, identityFact, 'Make the business name unmistakable in the title and H1.', 2);
  }
  if (!analysis.description) {
    signal('Missing meta description', 10, descriptionFact, 'Write a concise, location-specific meta description.', 2);
  }
  if (!analysis.viewport) {
    signal('No responsive viewport declaration', 18, viewportFact, 'Add a responsive viewport and test on phones.', 3);
  }
  if (page.bytes > 150_000) {
    signal('Heavy homepage payload', 10, weightFact, 'Compress images and defer non-critical scripts.', 2);
  }
  if (page.elapsedMs > 1500) {
    signal('Slow homepage response', 8, weightFact, 'Profile hosting and asset delivery.', 2);
  }
  if (!analysis.email && !analysis.phone && !analysis.hasContactForm) {
    signal('No direct contact action', 16, contactFact, 'Add a clear contact action above the fold.', 3);
  }
  if (!analysis.ordering) {
    signal('No online ordering or booking path', 8, orderFact, 'Test a simple order/reservation call to action.', 2);
  }
  if (!analysis.menuLink) {
    signal('No menu navigation link', 4, menuFact, 'Expose the menu directly in the primary navigation.', 1);
  }
  if (!analysis.hasLocalBusinessSchema) {
    signal('No local-business structured data', 5, schemaFact, 'Add LocalBusiness JSON-LD with verified details.', 1);
  }
  if (!analysis.hsts) {
    signal('HSTS header missing or zero', 4, hstsFact, 'Enable HSTS after confirming all subdomains use HTTPS.', 1);
  }
  if (analysis.copyrightYear && analysis.copyrightYear < new Date(checkedAt).getUTCFullYear() - 1) {
    const copyrightFact = facts.find((entry) => entry.statement.includes('copyright year'));
    signal('Stale copyright year', 7, copyrightFact, 'Refresh the footer and review time-sensitive content.', 2);
  }
  if (!analysis.social.length) {
    signal('No social profiles linked', 3, socialFact, 'Link active profiles so visitors can verify the business.', 1);
  }
  if (cityToken.length > 2 && !titleLower.includes(cityToken)) {
    signal('City absent from page title', 4, titleFact, 'Include the service city in the page title where natural.', 1);
  }

  signals.sort((a, b) => b.weight - a.weight);
  const score = Math.min(100, signals.reduce((total, entry) => total + entry.weight, 0));
  const priority = score >= 40 ? 'HOT' : score >= 20 ? 'WARM' : 'NURTURE';
  const top = signals.slice(0, 2);
  const opportunity = {
    headline:
      top.length === 0
        ? 'No material static-HTML gaps observed'
        : `${top.length === 1 ? 'One' : top.length} observable website gap${top.length === 1 ? '' : 's'} led by ${top[0].label.toLowerCase()}`,
    summary:
      top.length === 0
        ? 'The delivered homepage covers the basics NOVA checks. A deeper analytics and conversion review would be needed before proposing work.'
        : `${business.name} has a live, identifiable website. Observed gaps: ${top
            .map((entry) => entry.label.toLowerCase())
            .join(' and ')}. These are static-HTML observations, not measured revenue losses.`,
    signals
  };

  if (top.length) {
    assumptions.push({
      id: `${factPrefix}_a1`,
      type: 'assumption',
      statement: `Addressing “${top[0].label}” may improve how prospective customers find or contact ${business.name}.`,
      rationale:
        'This is an inference from observed HTML. No traffic, conversion, ranking or revenue data was collected, so impact is unproven.',
      basis: top.map((entry) => entry.factId),
      confidence: 'medium'
    });
  }
  assumptions.push({
    id: `${factPrefix}_a${assumptions.length + 1}`,
    type: 'assumption',
    statement: `${business.name} is a plausible fit for a website review, but budget, decision-maker and interest are unknown.`,
    rationale:
      'Fit is based only on a verified business listing and a live website. No contact, intent or commercial data was used.',
    basis: [identityFact.id, responseFact.id],
    confidence: 'low'
  });

  return {
    verified,
    state: 'VERIFIED',
    website: {
      url: websiteUrl,
      finalUrl: page.finalUrl,
      status: page.status,
      verified,
      title: analysis.title,
      generator: analysis.generator,
      bytes: page.bytes,
      elapsedMs: page.elapsedMs,
      checkedAt,
      identityMatch,
      locationMatch,
      limitation: null
    },
    facts,
    assumptions,
    opportunitySignals: signals,
    score,
    priority,
    opportunity,
    checks: {
      title: analysis.title || null,
      metaDescription: analysis.description || null,
      viewport: analysis.viewport,
      https: page.finalUrl.startsWith('https://'),
      hsts: analysis.hsts,
      social: analysis.social,
      email: analysis.email,
      phone: analysis.phone,
      contactForm: analysis.hasContactForm,
      ordering: analysis.ordering,
      menuLink: analysis.menuLink,
      structuredData: analysis.hasLocalBusinessSchema,
      analytics: analysis.analytics,
      copyrightYear: analysis.copyrightYear,
      platform: analysis.generator,
      bytes: page.bytes,
      elapsedMs: page.elapsedMs,
      identityMatch,
      locationMatch
    }
  };
}

import { ExecutionError } from '../lib/errors.js';
import { nowIso } from '../lib/ids.js';

const CHAIN_PATTERNS = [
  /\bstarbucks\b/i,
  /\bdunkin\b/i,
  /\bpanera\b/i,
  /\bmcdonald'?s\b/i,
  /\bsubway\b/i,
  /\bgreat harvest\b/i,
  /\binsomnia cookies\b/i,
  /\bnothing bundt cakes\b/i,
  /\bcinnabon\b/i
];

function cleanAddress(displayName) {
  return String(displayName ?? '')
    .split(',')
    .map((part) => part.trim())
    .filter(Boolean)
    .join(', ');
}

function normalizeWebsite(value) {
  if (!value) return null;
  let candidate = String(value).trim();
  if (!candidate) return null;
  if (candidate.startsWith('//')) candidate = `https:${candidate}`;
  if (!/^https?:\/\//i.test(candidate)) candidate = `https://${candidate}`;
  try {
    const url = new URL(candidate);
    if (!['http:', 'https:'].includes(url.protocol)) return null;
    return url.href;
  } catch {
    return null;
  }
}

function isGenericName(name) {
  return !name || /^(bakery|cafe|café|restaurant|coffee shop|the bakery)$/i.test(name.trim());
}

function isChain(name, tags) {
  return Boolean(tags?.brand) || CHAIN_PATTERNS.some((pattern) => pattern.test(name));
}

function normalizeCandidate(item) {
  const tags = item.extratags ?? {};
  const name = String(item.name ?? item.display_name?.split(',')[0] ?? '').trim();
  const websiteUrl = normalizeWebsite(tags.website ?? tags['contact:website'] ?? tags.url ?? tags['website:en']);
  return {
    name,
    category: tags.cuisine ?? item.type ?? 'business',
    location: cleanAddress(item.display_name),
    lat: item.lat ? Number(item.lat) : null,
    lon: item.lon ? Number(item.lon) : null,
    websiteUrl,
    osm: {
      type: item.osm_type ?? null,
      id: item.osm_id ?? null,
      url:
        item.osm_type && item.osm_id
          ? `https://www.openstreetmap.org/${item.osm_type}/${item.osm_id}`
          : null
    },
    tags: {
      brand: tags.brand ?? null,
      openingHours: tags.opening_hours ?? null,
      phone: tags.phone ?? null
    },
    discoveredAt: nowIso()
  };
}

/**
 * Discovery adapter backed by the public OpenStreetMap Nominatim API.
 * It is rate limited to one request per 1.1 seconds as required by the
 * Nominatim usage policy. Results are leads, not independently audited facts.
 */
export function createNominatimDiscovery(options = {}) {
  const {
    fetchImpl = globalThis.fetch,
    sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
    userAgent = 'DEEMANNIES-AGENT-HQ/2.0 (local research)',
    endpoint = 'https://nominatim.openstreetmap.org/search',
    minIntervalMs = 1100,
    timeoutMs = 20_000
  } = options;

  let lastRequest = 0;

  async function request(query, limit) {
    const wait = minIntervalMs - (Date.now() - lastRequest);
    if (wait > 0) await sleep(wait);
    lastRequest = Date.now();

    const url = new URL(endpoint);
    url.searchParams.set('format', 'jsonv2');
    url.searchParams.set('q', query);
    url.searchParams.set('addressdetails', '1');
    url.searchParams.set('extratags', '1');
    url.searchParams.set('limit', String(limit));
    url.searchParams.set('accept-language', 'en');

    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    let response;
    try {
      response = await fetchImpl(url, {
        headers: {
          'user-agent': userAgent,
          accept: 'application/json',
          'accept-language': 'en-US,en;q=0.8'
        },
        signal: controller.signal
      });
    } catch (error) {
      throw new ExecutionError(
        error?.name === 'AbortError' ? 'DISCOVERY_TIMEOUT' : 'DISCOVERY_UNAVAILABLE',
        error?.name === 'AbortError'
          ? 'OpenStreetMap discovery timed out.'
          : 'OpenStreetMap discovery was unreachable.',
        { recoverable: true, cause: error }
      );
    } finally {
      clearTimeout(timer);
    }

    if (response.status === 429) {
      throw new ExecutionError(
        'DISCOVERY_RATE_LIMITED',
        'OpenStreetMap rate-limited this research run. Wait a minute and retry.',
        { recoverable: true }
      );
    }
    if (!response.ok) {
      throw new ExecutionError(
        'DISCOVERY_REJECTED',
        `OpenStreetMap discovery returned HTTP ${response.status}.`,
        { recoverable: true }
      );
    }
    let data;
    try {
      data = await response.json();
    } catch (error) {
      throw new ExecutionError('DISCOVERY_BAD_RESPONSE', 'OpenStreetMap returned an unreadable response.', {
        recoverable: true,
        cause: error
      });
    }
    if (!Array.isArray(data)) {
      throw new ExecutionError('DISCOVERY_BAD_RESPONSE', 'OpenStreetMap returned an unexpected response.', {
        recoverable: true
      });
    }
    return { data, requestUrl: url.href };
  }

  async function discover({ niche, city, count }) {
    const cleanNiche = niche.trim();
    const cleanCity = city.trim();
    const shortCity = cleanCity.split(',')[0].trim();
    const queries = [...new Set([
      `${cleanNiche} in ${cleanCity}`,
      `${cleanNiche} ${cleanCity}`,
      `${cleanNiche} in ${shortCity}`
    ])];
    const limit = Math.min(20, Math.max(10, count * 4));
    const raw = [];
    const requests = [];
    const rejected = [];

    for (const query of queries) {
      const result = await request(query, limit);
      requests.push({ query, endpoint: result.requestUrl });
      raw.push(...result.data);
      const withWebsite = raw.filter((item) => normalizeWebsite(item.extratags?.website ?? item.extratags?.['contact:website']));
      if (withWebsite.length >= count * 2) break;
    }

    const seen = new Set();
    const candidates = [];
    for (const item of raw) {
      const candidate = normalizeCandidate(item);
      if (isGenericName(candidate.name)) {
        rejected.push({ name: candidate.name || '(unnamed)', reason: 'Generic or missing name' });
        continue;
      }
      if (isChain(candidate.name, item.extratags)) {
        rejected.push({ name: candidate.name, reason: 'Chain or franchise listing' });
        continue;
      }
      const key = candidate.websiteUrl
        ? `site:${new URL(candidate.websiteUrl).hostname.replace(/^www\./, '')}`
        : `name:${candidate.name.toLowerCase()}:${candidate.lat?.toFixed(3)}:${candidate.lon?.toFixed(3)}`;
      if (seen.has(key)) continue;
      seen.add(key);
      candidates.push(candidate);
    }

    candidates.sort((a, b) => {
      if (Boolean(a.websiteUrl) !== Boolean(b.websiteUrl)) return a.websiteUrl ? -1 : 1;
      return a.name.localeCompare(b.name);
    });

    return {
      candidates,
      requests,
      rejected: rejected.slice(0, 12),
      source: 'OpenStreetMap Nominatim',
      fetchedAt: nowIso()
    };
  }

  return { discover, name: 'nominatim' };
}

import { ExecutionError } from '../lib/errors.js';
import { nowIso } from '../lib/ids.js';
import { safeFetch } from '../lib/http-client.js';
import { auditWebsite } from './site-audit.js';

function uniqueSources(sources) {
  const seen = new Set();
  return sources.filter((source) => {
    if (!source?.url || seen.has(source.url)) return false;
    seen.add(source.url);
    return true;
  });
}

function osmFact(candidate, factPrefix, index, statement) {
  return {
    id: `${factPrefix}_f${index}`,
    type: 'verified',
    statement,
    source: {
      label: `OpenStreetMap listing for ${candidate.name}`,
      url: candidate.osm?.url ?? 'https://www.openstreetmap.org/',
      type: 'map-listing'
    },
    observedAt: candidate.discoveredAt,
    method: 'Public Nominatim search over OpenStreetMap community data'
  };
}

function buildNoWebsiteProspect(candidate, city, factPrefix, researchedAt) {
  const listing = osmFact(
    candidate,
    factPrefix,
    1,
    `OpenStreetMap lists “${candidate.name}” at ${candidate.location}.`
  );
  const noSite = osmFact(
    candidate,
    factPrefix,
    2,
    'The OpenStreetMap listing contains no website tag. Absence from this listing is not proof that the business has no website.'
  );
  return {
    id: `prospect_${factPrefix}`,
    name: candidate.name,
    location: candidate.location,
    category: candidate.category,
    coordinates: candidate.lat != null ? { lat: candidate.lat, lon: candidate.lon } : null,
    osm: candidate.osm,
    website: {
      url: null,
      finalUrl: null,
      status: null,
      verified: false,
      title: null,
      generator: null,
      bytes: null,
      elapsedMs: null,
      checkedAt: researchedAt,
      identityMatch: false,
      locationMatch: false,
      limitation: 'No website is listed in the source data; a manual search is required.'
    },
    verification: {
      status: 'SOURCE_ONLY',
      identity: 'SOURCE_LISTED',
      location: 'SOURCE_LISTED',
      website: 'NOT_LISTED',
      label: 'Business name and address are from OpenStreetMap only'
    },
    opportunity: {
      score: 0,
      priority: 'REVIEW',
      headline: 'No website listed in source data',
      summary:
        'NOVA found no website tag in the OpenStreetMap record. This is an evidence gap, not proof that no site exists.',
      signals: []
    },
    facts: [listing, noSite],
    assumptions: [
      {
        id: `${factPrefix}_a1`,
        type: 'assumption',
        statement: `${candidate.name} may need a website or may have an unlisted one; either way, manual verification is required before outreach.`,
        rationale: 'A missing OpenStreetMap tag is not evidence of a missing website.',
        basis: [listing.id, noSite.id],
        confidence: 'low'
      }
    ],
    sources: [candidate.osm?.url].filter(Boolean),
    researchedAt
  };
}

/**
 * NOVA's first real assignment.
 *
 * 1. Discover real businesses through OpenStreetMap/Nominatim.
 * 2. Inspect each official homepage directly over HTTP.
 * 3. Keep verified observations separate from assumptions.
 * 4. Return only what was actually observed, with a timestamp and source per fact.
 */
export function createResearchProvider(options = {}) {
  const {
    discovery,
    fetchPage = (url) => safeFetch(url),
    now = () => new Date(),
    sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))
  } = options;

  if (!discovery) throw new Error('Research provider requires a discovery adapter.');

  return {
    id: 'nova-prospect-research',
    name: 'NOVA Prospect Research',
    async execute(task, context = {}) {
      const { niche, city, count } = task.input;
      const report = context.reportProgress ?? (() => {});
      const startedAt = nowIso();
      const limitations = [];
      const screening = { candidateCount: 0, audited: 0, verifiedCount: 0, excluded: [] };

      report('DISCOVERING', 8, `Searching OpenStreetMap for ${niche} in ${city}.`);
      const found = await discovery.discover({ niche, city, count });
      screening.candidateCount = found.candidates.length;
      screening.excluded.push(...(found.rejected ?? []));

      if (!found.candidates.length) {
        throw new ExecutionError(
          'NO_CANDIDATES',
          `OpenStreetMap returned no local businesses for “${niche}” in “${city}”. Try a broader category or city.`,
          { recoverable: true }
        );
      }

      const auditLimit = Math.min(found.candidates.length, Math.max(count * 2, 6));
      const toAudit = found.candidates.slice(0, auditLimit);
      const audits = [];

      for (let index = 0; index < toAudit.length; index += 1) {
        const candidate = toAudit[index];
        const factPrefix = `p${index + 1}`;
        if (!candidate.websiteUrl) {
          audits.push({ candidate, factPrefix, audit: null, reason: 'No website tag in source data' });
          continue;
        }
        report(
          'AUDITING',
          20 + Math.round((index / Math.max(1, toAudit.length)) * 45),
          `Inspecting ${candidate.name} (${index + 1}/${toAudit.length}).`
        );
        let page;
        try {
          page = await fetchPage(candidate.websiteUrl);
        } catch (error) {
          page = {
            requestedUrl: candidate.websiteUrl,
            error: { message: error?.message ?? 'The homepage could not be reached.' },
            fetchedAt: nowIso()
          };
        }
        const audit = auditWebsite(
          { name: candidate.name, city, websiteUrl: candidate.websiteUrl },
          page,
          { now: now().toISOString(), factPrefix }
        );
        audits.push({
          candidate,
          factPrefix,
          audit,
          reason: audit.verified ? null : audit.website.limitation
        });
        screening.audited += 1;
        await sleep(300);
      }

      const withWebsite = audits.filter((entry) => entry.audit);
      const verified = withWebsite
        .filter((entry) => entry.audit.verified && entry.audit.website.identityMatch)
        .sort((a, b) => b.audit.score - a.audit.score);
      const liveButUnconfirmed = withWebsite
        .filter((entry) => entry.audit.verified && !entry.audit.website.identityMatch)
        .sort((a, b) => b.audit.score - a.audit.score);
      const review = withWebsite
        .filter((entry) => !entry.audit.verified)
        .sort((a, b) => a.candidate.name.localeCompare(b.candidate.name));
      const noWebsite = audits.filter((entry) => !entry.audit);

      const selected = [...verified, ...liveButUnconfirmed, ...review, ...noWebsite].slice(0, count);
      screening.verifiedCount = selected.filter((entry) => entry.audit?.verified).length;

      for (const entry of audits) {
        if (selected.includes(entry)) continue;
        const reason = entry.audit?.verified
          ? 'Screened out by opportunity ranking after the requested count was filled'
          : entry.reason ?? 'Not selected';
        screening.excluded.push({ name: entry.candidate.name, reason });
      }

      report('SYNTHESIZING', 72, `Synthesising ${selected.length} evidence-backed prospect record(s).`);
      const prospects = selected.map((entry, index) => {
        const { candidate, factPrefix, audit } = entry;
        const researchedAt = nowIso();
        if (!audit) {
          return buildNoWebsiteProspect(candidate, city, factPrefix, researchedAt);
        }

        const listingFact = osmFact(
          candidate,
          factPrefix,
          1,
          `OpenStreetMap lists “${candidate.name}” at ${candidate.location}.`
        );
        const websiteTagFact = osmFact(
          candidate,
          factPrefix,
          2,
          `OpenStreetMap lists ${candidate.websiteUrl} as the website for this business.`
        );
        // Re-number audit facts after the two source-listing facts.
        const auditFacts = audit.facts.map((fact, factIndex) => ({
          ...fact,
          id: `${factPrefix}_f${factIndex + 3}`
        }));
        const factIdMap = new Map(audit.facts.map((fact, factIndex) => [fact.id, `${factPrefix}_f${factIndex + 3}`]));
        const auditAssumptions = audit.assumptions.map((assumption, assumptionIndex) => ({
          ...assumption,
          id: `${factPrefix}_a${assumptionIndex + 1}`,
          basis: assumption.basis.map((id) => factIdMap.get(id) ?? id)
        }));
        const signals = audit.opportunity.signals.map((signal, signalIndex) => ({
          ...signal,
          id: `${factPrefix}_s${signalIndex + 1}`,
          factId: factIdMap.get(signal.factId) ?? signal.factId
        }));

        const extraFacts = [];
        if (audit.website.locationMatch) {
          const cityName = city.split(',')[0].trim();
          extraFacts.push({
            id: `${factPrefix}_f${auditFacts.length + 3}`,
            type: 'verified',
            statement: `The delivered homepage references “${cityName}”, consistent with the OpenStreetMap location.`,
            source: {
              label: `${candidate.name} homepage`,
              url: audit.website.finalUrl,
              type: 'website'
            },
            observedAt: audit.website.checkedAt,
            method: 'Static HTML text inspection (JavaScript not executed)'
          });
        }
        const allFacts = [listingFact, websiteTagFact, ...auditFacts, ...extraFacts];

        const overall =
          audit.verified && audit.website.identityMatch
            ? 'VERIFIED'
            : audit.verified
              ? 'PARTIAL'
              : 'PARTIAL';
        const verification = {
          status: overall,
          identity: audit.website.identityMatch ? 'MATCHED' : 'UNCONFIRMED',
          location: audit.website.locationMatch ? 'MATCHED' : 'SOURCE_LISTED',
          website: audit.verified ? 'VERIFIED' : audit.state,
          label:
            overall === 'VERIFIED'
              ? 'Name, listing, location and live website cross-checked'
              : 'One or more checks could not be confirmed'
        };

        const outreachAngle = audit.opportunity.signals.length
          ? `A concise, evidence-led teardown focused on “${audit.opportunity.signals[0].label}”${
              audit.opportunity.signals[1] ? ` and “${audit.opportunity.signals[1].label}”` : ''
            }.`
          : 'A positive check-in offering a deeper analytics and conversion review.';

        return {
          id: `prospect_${factPrefix}`,
          rank: index + 1,
          name: candidate.name,
          location: candidate.location,
          category: candidate.category,
          coordinates: candidate.lat != null ? { lat: candidate.lat, lon: candidate.lon } : null,
          osm: candidate.osm,
          website: audit.website,
          verification,
          opportunity: {
            score: audit.score,
            priority: audit.priority,
            headline: audit.opportunity.headline,
            summary: audit.opportunity.summary,
            signals,
            outreachAngle
          },
          checks: audit.checks,
          facts: allFacts,
          assumptions: [
            ...auditAssumptions,
            {
              id: `${factPrefix}_a${auditAssumptions.length + 1}`,
              type: 'assumption',
              statement: `Suggested outreach angle: ${outreachAngle}`,
              rationale: 'This is a messaging hypothesis based on observed HTML gaps, not a measured business outcome.',
              basis: signals.slice(0, 2).map((signal) => signal.factId),
              confidence: 'low'
            }
          ],
          sources: uniqueSources([
            ...allFacts.map((fact) => fact.source),
            candidate.osm?.url ? { label: 'OpenStreetMap', url: candidate.osm.url, type: 'map-listing' } : null
          ]).map((source) => source.url),
          researchedAt
        };
      });

      if (!prospects.length) {
        throw new ExecutionError(
          'NO_PROSPECTS',
          'Discovery found businesses, but none could be verified. No prospects were fabricated.',
          { recoverable: true, detail: { candidates: screening.candidateCount } }
        );
      }

      if (prospects.length < count) {
        limitations.push(
          `Requested ${count} prospects; returned ${prospects.length} because the remaining candidates could not be verified within the audit limit.`
        );
      }
      limitations.push(
        'Website findings come from static HTML inspection only. JavaScript-rendered content was not executed.',
        'OpenStreetMap is community-maintained and may be incomplete or stale.',
        'No traffic, conversion, revenue, contact or purchase-intent data was collected.',
        'No customer was contacted and no website was published or changed.'
      );

      screening.excluded = screening.excluded.slice(0, 20);

      const result = {
        assignment: {
          niche,
          city,
          requestedCount: count,
          returnedCount: prospects.length,
          requestedBy: task.input.requestedBy ?? 'HQ operator',
          provider: 'OpenStreetMap Nominatim + direct homepage inspection',
          startedAt,
          completedAt: nowIso()
        },
        prospects,
        methodology: [
          'Resolve real businesses from public OpenStreetMap data via Nominatim.',
          'Reject chains, franchises, generic names and duplicate domains.',
          'Fetch each official homepage directly over HTTP with SSRF and redirect checks.',
          'Inspect delivered HTML for identity, contact, ordering, mobile, performance and metadata signals.',
          'Rank observed gaps, then keep facts and assumptions in separate fields.'
        ],
        screening,
        limitations,
        generatedAt: nowIso()
      };

      report('DELIVERING', 92, 'Verifying that results are persisted and retrievable.');
      return result;
    }
  };
}

import { ExecutionError } from '../lib/errors.js';
import { newId, nowIso } from '../lib/ids.js';

/**
 * Prepares a human-reviewable outreach draft. It never resolves an email,
 * never sends a message and never changes an external account.
 */
export function createOutreachProvider({ store, now = nowIso }) {
  return {
    id: 'nova-outreach-draft',
    name: 'NOVA Outreach Draft',
    async execute(task) {
      const source = store.getTask(task.input.researchTaskId);
      if (!source) {
        throw new ExecutionError('SOURCE_TASK_NOT_FOUND', 'The research task for this draft no longer exists.', {
          status: 404,
          recoverable: false
        });
      }
      if (source.status !== 'COMPLETED' || !source.results?.prospects?.length) {
        throw new ExecutionError(
          'SOURCE_NOT_COMPLETE',
          'Outreach can only be drafted from a completed research task with delivered results.',
          { recoverable: true }
        );
      }
      const prospect = source.results.prospects.find((entry) => entry.id === task.input.prospectId);
      if (!prospect) {
        throw new ExecutionError('PROSPECT_NOT_FOUND', 'That prospect is not part of the selected research task.', {
          status: 404,
          recoverable: false
        });
      }

      const topSignal = prospect.opportunity?.signals?.[0];
      const signalFact = topSignal
        ? prospect.facts.find((fact) => fact.id === topSignal.factId)
        : null;
      const observation = signalFact?.statement ?? 'The homepage is live and identifiable.';
      const website = prospect.website?.finalUrl ?? prospect.website?.url;
      const createdAt = now();

      const subject = `A quick website observation for ${prospect.name}`;
      const body = [
        `Hi ${prospect.name} team,`,
        '',
        `I am with DEEMANNIE'S DIGITAL. I reviewed ${website ?? 'your public listing'} on ${createdAt.slice(0, 10)} and recorded one specific observation:`,
        '',
        `“${observation}”`,
        '',
        topSignal
          ? `That came from a static review of the homepage. It may be worth a closer look, especially if ${topSignal.label.toLowerCase()} is affecting how customers find or contact you.`
          : 'I did not find a material static-HTML gap, so a deeper analytics review would be the useful next step.',
        '',
        'I can prepare a short, no-obligation teardown with the exact evidence and a suggested fix. If this is not relevant, no follow-up is needed.',
        '',
        'Regards,',
        "DEEMANNIE'S DIGITAL — Research Desk"
      ].join('\n');

      const approvalId = newId('apr');
      return {
        requiresApproval: true,
        data: {
          draft: {
            id: newId('drf'),
            prospectId: prospect.id,
            prospectName: prospect.name,
            recipient: 'Not verified — manual lookup required',
            subject,
            body,
            createdAt
          },
          provenance: {
            researchTaskId: source.id,
            prospectId: prospect.id,
            evidenceFactId: signalFact?.id ?? null,
            evidence: signalFact
              ? { statement: signalFact.statement, source: signalFact.source, observedAt: signalFact.observedAt }
              : null
          },
          sendStatus: 'NOT_SENT',
          notice:
            'AGENT HQ never sends email. Approval only releases this draft for a human to review and send manually.'
        },
        approval: {
          id: approvalId,
          taskId: task.id,
          researchTaskId: source.id,
          prospectId: prospect.id,
          prospectName: prospect.name,
          subject,
          body,
          recipient: 'Not verified — manual lookup required',
          status: 'AWAITING_APPROVAL',
          createdAt,
          decision: null,
          sendStatus: 'NOT_SENT',
          notice:
            'Approval records intent only. No message is sent, no account is changed, and no money is spent by AGENT HQ.'
        }
      };
    }
  };
}

import { ExecutionError } from '../lib/errors.js';

export function createExecutionBridge({ providers }) {
  const registry = new Map(Object.entries(providers));
  return {
    list() {
      return [...registry.values()].map((provider) => ({ id: provider.id, name: provider.name }));
    },
    async execute(task, context) {
      const provider = registry.get(task.type);
      if (!provider) {
        throw new ExecutionError('NO_PROVIDER', `No execution provider is registered for “${task.type}”.`, {
          recoverable: false
        });
      }
      return provider.execute(task, context);
    }
  };
}

import { ValidationError } from './errors.js';

const TASK_TYPES = new Set(['prospect_research', 'outreach_draft']);

function clean(value) {
  return typeof value === 'string' ? value.replace(/\s+/g, ' ').trim() : '';
}

export function validateTaskSubmission(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    throw new ValidationError('Send a JSON object with a task type and input.');
  }
  const type = clean(body.type);
  if (!TASK_TYPES.has(type)) {
    throw new ValidationError('Unknown task type.', { allowed: [...TASK_TYPES] });
  }

  if (type === 'prospect_research') {
    const input = body.input;
    if (!input || typeof input !== 'object' || Array.isArray(input)) {
      throw new ValidationError('Research input must include a niche, city and count.');
    }
    const niche = clean(input.niche);
    const city = clean(input.city);
    const count = input.count === undefined ? 3 : Number(input.count);
    if (niche.length < 2 || niche.length > 80) {
      throw new ValidationError('Niche must be between 2 and 80 characters.');
    }
    if (city.length < 2 || city.length > 100) {
      throw new ValidationError('City must be between 2 and 100 characters.');
    }
    if (!Number.isInteger(count) || count < 1 || count > 5) {
      throw new ValidationError('Count must be a whole number from 1 to 5.');
    }
    const requestedBy = clean(input.requestedBy) || 'HQ operator';
    return {
      type,
      input: { niche, city, count, requestedBy: requestedBy.slice(0, 80) }
    };
  }

  const input = body.input;
  if (!input || typeof input !== 'object') {
    throw new ValidationError('Outreach input must reference a research task and prospect.');
  }
  const researchTaskId = clean(input.researchTaskId);
  const prospectId = clean(input.prospectId);
  if (!/^tsk_[a-f0-9]{12}$/.test(researchTaskId)) {
    throw new ValidationError('A valid research task ID is required.');
  }
  if (!/^prospect_[a-z0-9_]+$/i.test(prospectId) || prospectId.length > 80) {
    throw new ValidationError('A valid prospect ID is required.');
  }
  return { type, input: { researchTaskId, prospectId } };
}

export function validateApprovalDecision(body) {
  if (!body || typeof body !== 'object') {
    throw new ValidationError('Send a decision of approve or reject.');
  }
  const decision = clean(body.decision).toLowerCase();
  if (!['approve', 'reject'].includes(decision)) {
    throw new ValidationError('Decision must be approve or reject.');
  }
  return {
    decision,
    note: clean(body.note).slice(0, 500)
  };
}

import fs from 'node:fs';
import path from 'node:path';
import { newId, nowIso } from './lib/ids.js';
import { log } from './lib/log.js';

const TASK_LIMIT = 60;
const ACTIVITY_LIMIT = 250;
const APPROVAL_LIMIT = 100;
const EVENT_LIMIT = 40;

const ALLOWED_TRANSITIONS = {
  QUEUED: new Set(['RUNNING', 'FAILED']),
  RUNNING: new Set(['COMPLETED', 'FAILED', 'AWAITING_APPROVAL']),
  AWAITING_APPROVAL: new Set([]),
  COMPLETED: new Set([]),
  FAILED: new Set([])
};

export const TASK_STATUSES = ['QUEUED', 'RUNNING', 'COMPLETED', 'FAILED', 'AWAITING_APPROVAL'];

function baseState() {
  const createdAt = nowIso();
  return {
    schemaVersion: 2,
    revision: 0,
    createdAt,
    meta: {
      phase: '02',
      checkpoint: {
        requested: '870d509',
        found: false,
        baselineHead: '2aee5e6',
        note: 'The requested checkpoint was not present in this repository at build time.'
      },
      seeded: false,
      seededFrom: null,
      seededAt: null,
      sourceGeneratedAt: null
    },
    org: {
      name: "DEEMANNIE'S DIGITAL",
      unit: 'AGENT HQ',
      mode: 'REAL OPERATIONS'
    },
    agent: {
      id: 'nova',
      name: 'NOVA',
      callsign: 'NOVA-01',
      role: 'Research & Opportunity Lead',
      status: 'IDLE',
      currentTaskId: null,
      lastActiveAt: null,
      lastTaskId: null,
      lastTaskStatus: null,
      lastError: null,
      stats: { submitted: 0, completed: 0, failed: 0, awaiting: 0 },
      capabilities: [
        'OpenStreetMap discovery',
        'Direct homepage inspection',
        'Evidence synthesis',
        'Approval-gated outreach drafts'
      ]
    },
    tasks: [],
    approvals: [],
    activity: []
  };
}

function normalizeLoaded(state) {
  const fresh = baseState();
  return {
    ...fresh,
    ...state,
    meta: { ...fresh.meta, ...(state.meta ?? {}) },
    org: { ...fresh.org, ...(state.org ?? {}) },
    agent: {
      ...fresh.agent,
      ...(state.agent ?? {}),
      stats: { ...fresh.agent.stats, ...(state.agent?.stats ?? {}) }
    },
    tasks: Array.isArray(state.tasks) ? state.tasks.slice(0, TASK_LIMIT) : [],
    approvals: Array.isArray(state.approvals) ? state.approvals.slice(0, APPROVAL_LIMIT) : [],
    activity: Array.isArray(state.activity) ? state.activity.slice(0, ACTIVITY_LIMIT) : []
  };
}

export class Store {
  constructor({ dataDir, seedPath = null, now = nowIso } = {}) {
    if (!dataDir) throw new Error('Store requires a data directory.');
    this.dataDir = dataDir;
    this.statePath = path.join(dataDir, 'state.json');
    this.seedPath = seedPath;
    this.now = now;
    this.subscribers = new Set();
    fs.mkdirSync(dataDir, { recursive: true });
    this.state = this.#load();
  }

  #load() {
    if (fs.existsSync(this.statePath)) {
      const parsed = JSON.parse(fs.readFileSync(this.statePath, 'utf8'));
      return normalizeLoaded(parsed);
    }
    if (this.seedPath && fs.existsSync(this.seedPath)) {
      const seed = normalizeLoaded(JSON.parse(fs.readFileSync(this.seedPath, 'utf8')));
      seed.meta.seeded = true;
      seed.meta.seededFrom = path.basename(this.seedPath);
      seed.meta.seededAt = nowIso();
      seed.meta.sourceGeneratedAt = seed.meta.sourceGeneratedAt ?? seed.tasks?.[0]?.completedAt ?? null;
      seed.revision = 0;
      seed.agent.status = 'IDLE';
      seed.agent.currentTaskId = null;
      for (const task of seed.tasks) {
        if (task.status === 'RUNNING' || task.status === 'QUEUED') {
          task.status = 'FAILED';
          task.error = {
            code: 'INTERRUPTED',
            message: 'Archived task was not running when the archive was restored.',
            recoverable: true
          };
        }
      }
      log.info('state.seeded', { tasks: seed.tasks.length, sourceGeneratedAt: seed.meta.sourceGeneratedAt });
      return seed;
    }
    return baseState();
  }

  #save(reason, taskId = null) {
    this.state.revision += 1;
    const temp = `${this.statePath}.${process.pid}.tmp`;
    fs.writeFileSync(temp, JSON.stringify(this.state, null, 2));
    fs.renameSync(temp, this.statePath);
    this.#emit(reason, taskId);
  }

  #emit(reason, taskId) {
    const payload = { reason, taskId, revision: this.state.revision, at: nowIso() };
    for (const subscriber of this.subscribers) {
      try {
        subscriber(payload);
      } catch (error) {
        log.warn('state.subscriber_failed', { message: error.message });
      }
    }
  }

  subscribe(listener) {
    this.subscribers.add(listener);
    return () => this.subscribers.delete(listener);
  }

  snapshot() {
    return structuredClone(this.state);
  }

  getTask(id) {
    return this.state.tasks.find((task) => task.id === id) ?? null;
  }

  readPersistedTask(id) {
    if (!fs.existsSync(this.statePath)) return null;
    const persisted = JSON.parse(fs.readFileSync(this.statePath, 'utf8'));
    return persisted.tasks?.find((task) => task.id === id) ?? null;
  }

  #activity(type, message, extra = {}) {
    this.state.activity.unshift({
      id: newId('act'),
      at: nowIso(),
      type,
      level: extra.level ?? 'info',
      message,
      ...extra
    });
    this.state.activity = this.state.activity.slice(0, ACTIVITY_LIMIT);
  }

  #taskEvent(task, status, message, extra = {}) {
    task.events ??= [];
    task.events.push({
      at: nowIso(),
      status,
      message,
      ...extra
    });
    task.events = task.events.slice(-EVENT_LIMIT);
  }

  createTask({ type, input, title, retryOf = null }) {
    const at = nowIso();
    const task = {
      id: newId('tsk'),
      type,
      title,
      status: 'QUEUED',
      input,
      createdAt: at,
      updatedAt: at,
      queuedAt: at,
      startedAt: null,
      completedAt: null,
      durationMs: null,
      attempts: 1,
      retryOf,
      progress: { phase: 'QUEUED', percent: 0, message: 'Waiting for the execution bridge.' },
      events: [],
      results: null,
      error: null,
      delivery: null,
      approvalId: null,
      approvalDecision: null
    };
    this.#taskEvent(task, 'QUEUED', 'Task accepted and queued for the execution bridge.');
    this.state.tasks.unshift(task);
    this.state.tasks = this.state.tasks.slice(0, TASK_LIMIT);
    this.state.agent.stats.submitted += 1;
    this.#activity('TASK_QUEUED', `${title} queued.`, { taskId: task.id, type });
    this.#save('task.queued', task.id);
    return structuredClone(task);
  }

  transitionTask(id, nextStatus, patch = {}) {
    const task = this.getTask(id);
    if (!task) throw new Error(`Unknown task: ${id}`);
    if (!ALLOWED_TRANSITIONS[task.status]?.has(nextStatus)) {
      throw new Error(`Invalid task transition ${task.status} → ${nextStatus}`);
    }
    task.status = nextStatus;
    task.updatedAt = nowIso();
    Object.assign(task, patch);

    if (nextStatus === 'RUNNING') {
      task.startedAt ??= nowIso();
      task.progress = patch.progress ?? { phase: 'RUNNING', percent: 1, message: 'Execution started.' };
      this.state.agent.status = 'RUNNING';
      this.state.agent.currentTaskId = task.id;
      this.state.agent.lastActiveAt = task.startedAt;
      this.state.agent.lastTaskId = task.id;
      this.state.agent.lastTaskStatus = 'RUNNING';
      this.#taskEvent(task, 'RUNNING', task.progress.message, { phase: task.progress.phase });
      this.#activity('TASK_RUNNING', `${task.title} started.`, { taskId: task.id });
    }

    this.#save(`task.${nextStatus.toLowerCase()}`, task.id);
    return structuredClone(task);
  }

  setProgress(id, { phase, percent, message }) {
    const task = this.getTask(id);
    if (!task || task.status !== 'RUNNING') return;
    const previousPhase = task.progress?.phase;
    task.progress = {
      phase,
      percent: Math.max(task.progress?.percent ?? 0, Math.min(99, Math.round(percent))),
      message
    };
    task.updatedAt = nowIso();
    if (phase !== previousPhase) {
      this.#taskEvent(task, 'RUNNING', message, { phase });
    }
    this.state.agent.lastActiveAt = task.updatedAt;
    this.#save('task.progress', task.id);
  }

  attachResults(id, results) {
    const task = this.getTask(id);
    if (!task || task.status !== 'RUNNING') throw new Error('Results can only attach to a running task.');
    task.results = results;
    task.updatedAt = nowIso();
    this.#save('task.results', task.id);
    return structuredClone(task);
  }

  completeTask(id, delivery) {
    const task = this.getTask(id);
    if (!task) throw new Error(`Unknown task: ${id}`);
    if (task.status !== 'RUNNING') throw new Error('Only a running task can complete.');
    if (!task.results) throw new Error('A task cannot complete without results.');
    task.status = 'COMPLETED';
    task.completedAt = nowIso();
    task.durationMs = new Date(task.completedAt) - new Date(task.startedAt);
    task.updatedAt = task.completedAt;
    task.delivery = delivery;
    task.progress = { phase: 'COMPLETED', percent: 100, message: 'Results persisted and delivered.' };
    this.state.agent.status = 'IDLE';
    this.state.agent.currentTaskId = null;
    this.state.agent.lastActiveAt = task.completedAt;
    this.state.agent.lastTaskStatus = 'COMPLETED';
    this.state.agent.lastError = null;
    this.state.agent.stats.completed += 1;
    this.#taskEvent(task, 'COMPLETED', 'Results persisted and delivered to the AGENT HQ interface.', {
      delivery: delivery.method
    });
    const prospectCount = task.results.prospects?.length;
    this.#activity(
      'TASK_COMPLETED',
      prospectCount
        ? `${task.title} completed with ${prospectCount} evidence-backed prospect(s).`
        : `${task.title} completed.`,
      { taskId: task.id }
    );
    this.#save('task.completed', task.id);
    return structuredClone(task);
  }

  awaitApproval(id, { results, approvalId, delivery }) {
    const task = this.getTask(id);
    if (!task) throw new Error(`Unknown task: ${id}`);
    if (task.status !== 'RUNNING') throw new Error('Only a running task can await approval.');
    task.status = 'AWAITING_APPROVAL';
    task.results = results;
    task.approvalId = approvalId;
    task.completedAt = null;
    task.updatedAt = nowIso();
    task.durationMs = new Date(task.updatedAt) - new Date(task.startedAt);
    task.delivery = delivery;
    task.progress = {
      phase: 'AWAITING_APPROVAL',
      percent: 100,
      message: 'Draft delivered. Human approval required; nothing was sent.'
    };
    this.state.agent.status = 'IDLE';
    this.state.agent.currentTaskId = null;
    this.state.agent.lastActiveAt = task.updatedAt;
    this.state.agent.lastTaskStatus = 'AWAITING_APPROVAL';
    this.state.agent.stats.awaiting += 1;
    this.#taskEvent(task, 'AWAITING_APPROVAL', 'Outreach draft delivered to the approval queue. Nothing was sent.');
    this.#activity('TASK_AWAITING_APPROVAL', `${task.title} is awaiting human approval.`, { taskId: task.id });
    this.#save('task.awaiting_approval', task.id);
    return structuredClone(task);
  }

  failTask(id, error) {
    const task = this.getTask(id);
    if (!task) throw new Error(`Unknown task: ${id}`);
    if (!ALLOWED_TRANSITIONS[task.status]?.has('FAILED')) {
      throw new Error(`Task ${task.status} cannot fail.`);
    }
    task.status = 'FAILED';
    task.completedAt = nowIso();
    task.updatedAt = task.completedAt;
    task.durationMs = task.startedAt ? new Date(task.completedAt) - new Date(task.startedAt) : 0;
    task.error = error;
    task.progress = { phase: 'FAILED', percent: 0, message: error.message };
    this.state.agent.status = 'IDLE';
    this.state.agent.currentTaskId = null;
    this.state.agent.lastActiveAt = task.completedAt;
    this.state.agent.lastTaskStatus = 'FAILED';
    this.state.agent.lastError = { code: error.code, message: error.message, at: task.completedAt };
    this.state.agent.stats.failed += 1;
    this.#taskEvent(task, 'FAILED', error.message, { code: error.code });
    this.#activity('TASK_FAILED', `${task.title} failed: ${error.message}`, {
      taskId: task.id,
      level: 'error'
    });
    this.#save('task.failed', task.id);
    return structuredClone(task);
  }

  addApproval(approval) {
    this.state.approvals.unshift(approval);
    this.state.approvals = this.state.approvals.slice(0, APPROVAL_LIMIT);
    this.#activity('APPROVAL_CREATED', `Outreach draft for ${approval.prospectName} awaits approval.`, {
      taskId: approval.taskId,
      approvalId: approval.id
    });
    this.#save('approval.created', approval.taskId);
    return structuredClone(approval);
  }

  getApproval(id) {
    return this.state.approvals.find((approval) => approval.id === id) ?? null;
  }

  decideApproval(id, { decision, note }) {
    const approval = this.getApproval(id);
    if (!approval) return null;
    if (approval.status !== 'AWAITING_APPROVAL') {
      throw new Error('This approval has already been decided.');
    }
    const at = nowIso();
    approval.status = decision === 'approve' ? 'APPROVED' : 'REJECTED';
    approval.decision = { at, decision, note: note || null, by: 'HQ operator' };
    approval.sendStatus = 'NOT_SENT';
    const task = this.getTask(approval.taskId);
    if (task) {
      task.approvalDecision = approval.decision;
      task.updatedAt = at;
      this.#taskEvent(
        task,
        'AWAITING_APPROVAL',
        decision === 'approve'
          ? 'Draft approved for manual use. AGENT HQ did not send it.'
          : 'Draft rejected. Nothing was sent.'
      );
    }
    this.#activity(
      'APPROVAL_DECIDED',
      decision === 'approve'
        ? `Draft for ${approval.prospectName} approved for manual use. No message sent.`
        : `Draft for ${approval.prospectName} rejected. No message sent.`,
      { approvalId: id, taskId: approval.taskId, level: decision === 'approve' ? 'info' : 'warn' }
    );
    this.#save('approval.decided', approval.taskId);
    return structuredClone(approval);
  }

  recoverInterrupted() {
    const interrupted = this.state.tasks.filter((task) => task.status === 'RUNNING');
    for (const task of interrupted) {
      task.error = {
        code: 'INTERRUPTED',
        message: 'Execution was interrupted by a server restart. Retry to run it again.',
        recoverable: true
      };
      task.status = 'FAILED';
      task.completedAt = nowIso();
      task.updatedAt = task.completedAt;
      task.progress = { phase: 'FAILED', percent: 0, message: task.error.message };
      this.#taskEvent(task, 'FAILED', task.error.message, { code: 'INTERRUPTED' });
      this.state.agent.stats.failed += 1;
    }
    const queued = this.state.tasks.filter((task) => task.status === 'QUEUED').map((task) => task.id);
    this.state.agent.status = 'IDLE';
    this.state.agent.currentTaskId = null;
    if (interrupted.length) {
      this.#activity('TASK_INTERRUPTED', `${interrupted.length} interrupted task(s) marked failed and recoverable.`, {
        level: 'warn'
      });
      this.#save('recovery.interrupted');
    }
    return { interrupted: interrupted.map((task) => task.id), queued };
  }

  metrics() {
    const tasks = this.state.tasks;
    const completed = tasks.filter((task) => task.status === 'COMPLETED');
    const failed = tasks.filter((task) => task.status === 'FAILED');
    const research = completed.filter((task) => task.type === 'prospect_research');
    const prospects = research.flatMap((task) => task.results?.prospects ?? []);
    const facts = prospects.reduce((total, prospect) => total + (prospect.facts?.length ?? 0), 0);
    const assumptions = prospects.reduce((total, prospect) => total + (prospect.assumptions?.length ?? 0), 0);
    const durations = completed.map((task) => task.durationMs).filter((value) => Number.isFinite(value));
    return {
      totalTasks: tasks.length,
      completed: completed.length,
      failed: failed.length,
      running: tasks.filter((task) => task.status === 'RUNNING').length,
      queued: tasks.filter((task) => task.status === 'QUEUED').length,
      awaitingApproval: tasks.filter((task) => task.status === 'AWAITING_APPROVAL').length,
      researchRuns: research.length,
      prospects: prospects.length,
      verifiedProspects: prospects.filter((prospect) => prospect.verification?.status === 'VERIFIED').length,
      facts,
      assumptions,
      successRate:
        completed.length + failed.length === 0
          ? null
          : Math.round((completed.length / (completed.length + failed.length)) * 100),
      averageDurationMs: durations.length
        ? Math.round(durations.reduce((total, value) => total + value, 0) / durations.length)
        : null,
      lastCompletedAt: completed[0]?.completedAt ?? null,
      pendingApprovals: this.state.approvals.filter((approval) => approval.status === 'AWAITING_APPROVAL').length
    };
  }

  publicSnapshot() {
    const state = this.snapshot();
    const latestResearch = state.tasks.find(
      (task) => task.type === 'prospect_research' && task.status === 'COMPLETED' && task.results?.prospects?.length
    );
    return {
      schemaVersion: state.schemaVersion,
      revision: state.revision,
      generatedAt: nowIso(),
      phase: state.meta.phase,
      org: state.org,
      meta: state.meta,
      agent: state.agent,
      metrics: this.metrics(),
      tasks: state.tasks,
      approvals: state.approvals,
      activity: state.activity.slice(0, 40),
      latestResearchTaskId: latestResearch?.id ?? null,
      statuses: TASK_STATUSES,
      services: {
        bridge: { status: 'READY', label: 'Execution bridge' },
        discovery: { status: 'READY', label: 'OpenStreetMap / Nominatim' },
        inspection: { status: 'READY', label: 'Direct HTTP homepage audit' },
        delivery: { status: 'READY', label: 'Persisted JSON + HTTP API + SSE' },
        outbound: { status: 'LOCKED', label: 'Email / publishing / spending' }
      }
    };
  }
}

