import { createHash } from 'node:crypto';
import { ExecutionError, ValidationError, toPublicError } from './lib/errors.js';
import { nowIso } from './lib/ids.js';
import { log } from './lib/log.js';
import { validateTaskSubmission } from './validation.js';

function hashResult(results) {
  return createHash('sha256').update(JSON.stringify(results)).digest('hex').slice(0, 16);
}

function titleFor(store, payload) {
  if (payload.type === 'prospect_research') {
    const { count, niche, city } = payload.input;
    return `Research ${count} ${niche} prospect${count === 1 ? '' : 's'} in ${city}`;
  }
  const source = store.getTask(payload.input.researchTaskId);
  const prospect = source?.results?.prospects?.find((entry) => entry.id === payload.input.prospectId);
  return `Draft outreach for ${prospect?.name ?? 'selected prospect'}`;
}

export function createTaskService({ store, bridge, logger = log }) {
  const queue = [];
  const idleWaiters = [];
  let active = false;

  function enqueue(taskId) {
    queue.push(taskId);
    void pump();
  }

  async function pump() {
    if (active) return;
    active = true;
    try {
      while (queue.length) {
        const taskId = queue.shift();
        await run(taskId);
      }
    } finally {
      active = false;
      if (!queue.length) {
        for (const resolve of idleWaiters.splice(0)) resolve();
      }
    }
  }

  function whenIdle() {
    if (!active && !queue.length) return Promise.resolve();
    return new Promise((resolve) => idleWaiters.push(resolve));
  }

  async function run(taskId) {
    const queued = store.getTask(taskId);
    if (!queued || queued.status !== 'QUEUED') return;

    store.transitionTask(taskId, 'RUNNING', {
      progress: { phase: 'STARTING', percent: 1, message: 'Execution bridge accepted the task.' }
    });
    logger.info('task.started', { taskId, type: queued.type });

    try {
      const output = await bridge.execute(store.getTask(taskId), {
        reportProgress: (phase, percent, message) => {
          const current = store.getTask(taskId);
          if (current?.status === 'RUNNING') store.setProgress(taskId, { phase, percent, message });
        }
      });

      if (!output || typeof output !== 'object') {
        throw new ExecutionError('EMPTY_RESULT', 'The execution provider returned no result.', {
          recoverable: true
        });
      }

      const requiresApproval = Boolean(output.requiresApproval);
      const results = requiresApproval ? output.data : output.data ?? output;
      if (!results || typeof results !== 'object') {
        throw new ExecutionError('EMPTY_RESULT', 'The execution provider returned an empty result.', {
          recoverable: true
        });
      }

      if (requiresApproval) {
        if (!output.approval?.id) {
          throw new ExecutionError('APPROVAL_RECORD_MISSING', 'The approval-gated task produced no approval record.', {
            recoverable: true
          });
        }
        store.addApproval(output.approval);
        store.attachResults(taskId, results);
        const persisted = store.readPersistedTask(taskId);
        if (!persisted?.results || !store.getApproval(output.approval.id)) {
          throw new ExecutionError(
            'DELIVERY_FAILED',
            'The draft could not be read back from persistent storage. Task was not marked delivered.',
            { recoverable: true }
          );
        }
        const delivery = {
          verified: true,
          method: 'Persisted JSON + approval queue + HTTP API + SSE',
          surfaces: ['state.json', 'GET /api/state', 'approval queue', 'SSE update'],
          deliveredAt: nowIso(),
          resultHash: hashResult(results)
        };
        store.awaitApproval(taskId, {
          results,
          approvalId: output.approval.id,
          delivery
        });
        const readback = store.readPersistedTask(taskId);
        if (readback?.status !== 'AWAITING_APPROVAL' || !readback.delivery?.verified) {
          throw new ExecutionError('DELIVERY_FAILED', 'Approval delivery could not be verified.', {
            recoverable: true
          });
        }
        logger.info('task.awaiting_approval', { taskId, approvalId: output.approval.id });
        return;
      }

      store.attachResults(taskId, results);
      const persisted = store.readPersistedTask(taskId);
      if (!persisted?.results) {
        throw new ExecutionError(
          'DELIVERY_FAILED',
          'Results could not be read back from persistent storage. Task was not marked complete.',
          { recoverable: true }
        );
      }

      const delivery = {
        verified: true,
        method: 'Persisted JSON + HTTP API + SSE',
        surfaces: ['state.json', 'GET /api/state', 'GET /api/tasks/:id', 'SSE update'],
        deliveredAt: nowIso(),
        resultHash: hashResult(results)
      };
      store.completeTask(taskId, delivery);
      const readback = store.readPersistedTask(taskId);
      if (readback?.status !== 'COMPLETED' || !readback.delivery?.verified) {
        throw new ExecutionError('DELIVERY_FAILED', 'Completion could not be verified after persistence.', {
          recoverable: true
        });
      }
      logger.info('task.completed', { taskId, durationMs: readback.durationMs });
    } catch (error) {
      const publicError = toPublicError(error);
      logger.error('task.failed', {
        taskId,
        code: publicError.code,
        message: publicError.message
      });
      const current = store.getTask(taskId);
      if (current?.status === 'RUNNING') {
        store.failTask(taskId, publicError);
      } else {
        logger.error('task.failure_after_terminal_state', {
          taskId,
          status: current?.status,
          code: publicError.code
        });
      }
    }
  }

  function submit(rawBody) {
    const payload = validateTaskSubmission(rawBody);
    const task = store.createTask({
      type: payload.type,
      input: payload.input,
      title: titleFor(store, payload)
    });
    enqueue(task.id);
    return task;
  }

  function retry(taskId) {
    const original = store.getTask(taskId);
    if (!original) return null;
    if (original.status !== 'FAILED') {
      throw new ValidationError('Only failed tasks can be retried.');
    }
    const task = store.createTask({
      type: original.type,
      input: original.input,
      title: `Retry: ${original.title}`,
      retryOf: original.id,
      attempts: (original.attempts ?? 1) + 1
    });
    enqueue(task.id);
    return task;
  }

  function recover() {
    const result = store.recoverInterrupted();
    for (const taskId of result.queued) enqueue(taskId);
    return result;
  }

  return { submit, retry, recover, whenIdle, run };
}

import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { createExecutionBridge } from './execution/bridge.js';
import { createNominatimDiscovery } from './execution/discovery.js';
import { createOutreachProvider } from './execution/outreach-provider.js';
import { createResearchProvider } from './execution/research-provider.js';
import { safeFetch } from './lib/http-client.js';
import { AppError, ValidationError, statusForError, toPublicError } from './lib/errors.js';
import { log } from './lib/log.js';
import { Store } from './store.js';
import { createTaskService } from './task-service.js';
import { validateApprovalDecision } from './validation.js';

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
  '.webmanifest': 'application/manifest+json'
};

const SECURITY_HEADERS = {
  'X-Content-Type-Options': 'nosniff',
  'X-Frame-Options': 'DENY',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'Cross-Origin-Opener-Policy': 'same-origin',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=(), payment=()',
  'Content-Security-Policy':
    "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; font-src 'self'; object-src 'none'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'"
};

function sendJson(res, status, payload) {
  const body = JSON.stringify(payload);
  res.writeHead(status, {
    ...SECURITY_HEADERS,
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
    'Cache-Control': 'no-store'
  });
  res.end(body);
}

function readJsonBody(req, maxBytes = 64 * 1024) {
  return new Promise((resolve, reject) => {
    let total = 0;
    const chunks = [];
    req.on('data', (chunk) => {
      total += chunk.length;
      if (total > maxBytes) {
        reject(new AppError('BODY_TOO_LARGE', 'Request body is too large.', { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      if (!chunks.length) {
        reject(new ValidationError('A JSON request body is required.'));
        return;
      }
      try {
        resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')));
      } catch {
        reject(new ValidationError('Request body must be valid JSON.'));
      }
    });
    req.on('error', reject);
  });
}

function serveStatic(req, res, pathname, publicDir) {
  if (!['GET', 'HEAD'].includes(req.method)) {
    sendJson(res, 405, { error: { code: 'METHOD_NOT_ALLOWED', message: 'Method not allowed.' } });
    return;
  }
  let decoded;
  try {
    decoded = decodeURIComponent(pathname);
  } catch {
    sendJson(res, 400, { error: { code: 'BAD_PATH', message: 'Invalid request path.' } });
    return;
  }
  if (decoded.includes('\0')) {
    sendJson(res, 400, { error: { code: 'BAD_PATH', message: 'Invalid request path.' } });
    return;
  }
  const relative = decoded === '/' ? 'index.html' : decoded.replace(/^\/+/, '');
  const file = path.resolve(publicDir, relative);
  if (file !== publicDir && !file.startsWith(publicDir + path.sep)) {
    sendJson(res, 404, { error: { code: 'NOT_FOUND', message: 'Not found.' } });
    return;
  }
  let stat;
  try {
    stat = fs.statSync(file);
  } catch {
    sendJson(res, 404, { error: { code: 'NOT_FOUND', message: 'Not found.' } });
    return;
  }
  if (!stat.isFile()) {
    sendJson(res, 404, { error: { code: 'NOT_FOUND', message: 'Not found.' } });
    return;
  }
  const body = fs.readFileSync(file);
  res.writeHead(200, {
    ...SECURITY_HEADERS,
    'Content-Type': MIME[path.extname(file).toLowerCase()] ?? 'application/octet-stream',
    'Content-Length': body.length,
    'Cache-Control': 'no-cache'
  });
  if (req.method === 'HEAD') res.end();
  else res.end(body);
}

export function createApp(options = {}) {
  const {
    dataDir,
    seedPath = null,
    publicDir,
    discovery,
    fetchPage,
    bridge: injectedBridge,
    now = () => new Date().toISOString(),
    logger = log
  } = options;

  if (!dataDir) throw new Error('createApp requires dataDir.');
  if (!publicDir) throw new Error('createApp requires publicDir.');

  const store = new Store({ dataDir, seedPath });
  const researchProvider = createResearchProvider({
    discovery:
      discovery ??
      createNominatimDiscovery({
        userAgent: options.userAgent
      }),
    fetchPage: fetchPage ?? ((url) => safeFetch(url, { userAgent: options.userAgent })),
    now: typeof now === 'function' ? () => new Date(now()) : () => new Date()
  });
  const outreachProvider = createOutreachProvider({ store, now });
  const bridge =
    injectedBridge ??
    createExecutionBridge({
      providers: {
        prospect_research: researchProvider,
        outreach_draft: outreachProvider
      }
    });
  const taskService = createTaskService({ store, bridge, logger });
  taskService.recover();

  const sseClients = new Set();
  const rate = new Map();
  const startedAt = Date.now();
  const unsubscribe = store.subscribe((event) => {
    for (const client of sseClients) {
      client.write(`event: update\ndata: ${JSON.stringify(event)}\n\n`);
    }
  });

  function allowWrite(ip) {
    const windowMs = 60_000;
    const limit = 30;
    const nowMs = Date.now();
    const current = rate.get(ip);
    if (!current || nowMs - current.start > windowMs) {
      rate.set(ip, { start: nowMs, count: 1 });
      return true;
    }
    current.count += 1;
    return current.count <= limit;
  }

  async function handleApi(req, res, url) {
    const pathname = url.pathname;

    if (req.method === 'GET' && pathname === '/api/health') {
      sendJson(res, 200, {
        ok: true,
        version: '2.0.0',
        now: new Date().toISOString(),
        uptimeMs: Date.now() - startedAt,
        bridge: bridge.list(),
        storage: 'Local atomic JSON store',
        execution: 'OpenStreetMap discovery + direct HTTP homepage inspection',
        outbound: 'LOCKED — no email, publishing or spending',
        seeded: store.snapshot().meta.seeded
      });
      return;
    }

    if (req.method === 'GET' && pathname === '/api/state') {
      sendJson(res, 200, store.publicSnapshot());
      return;
    }

    if (req.method === 'GET' && pathname === '/api/tasks') {
      sendJson(res, 200, { tasks: store.snapshot().tasks, revision: store.snapshot().revision });
      return;
    }

    if (req.method === 'POST' && pathname === '/api/tasks') {
      const ip = req.socket.remoteAddress ?? 'unknown';
      if (!allowWrite(ip)) {
        sendJson(res, 429, {
          error: {
            code: 'RATE_LIMITED',
            message: 'Too many task submissions. Wait a minute and retry.',
            recoverable: true
          }
        });
        return;
      }
      const body = await readJsonBody(req);
      const task = taskService.submit(body);
      sendJson(res, 202, { task });
      return;
    }

    const taskMatch = /^\/api\/tasks\/(tsk_[a-f0-9]{12})(\/retry)?$/.exec(pathname);
    if (taskMatch) {
      const taskId = taskMatch[1];
      if (req.method === 'GET' && !taskMatch[2]) {
        const task = store.getTask(taskId);
        if (!task) {
          sendJson(res, 404, { error: { code: 'TASK_NOT_FOUND', message: 'Task not found.' } });
          return;
        }
        sendJson(res, 200, { task });
        return;
      }
      if (req.method === 'POST' && taskMatch[2]) {
        const task = taskService.retry(taskId);
        if (!task) {
          sendJson(res, 404, { error: { code: 'TASK_NOT_FOUND', message: 'Task not found.' } });
          return;
        }
        sendJson(res, 202, { task });
        return;
      }
    }

    if (req.method === 'GET' && pathname === '/api/approvals') {
      sendJson(res, 200, { approvals: store.snapshot().approvals });
      return;
    }

    const approvalMatch = /^\/api\/approvals\/(apr_[a-f0-9]{12})\/decision$/.exec(pathname);
    if (req.method === 'POST' && approvalMatch) {
      const body = await readJsonBody(req);
      const decision = validateApprovalDecision(body);
      let approval;
      try {
        approval = store.decideApproval(approvalMatch[1], decision);
      } catch (error) {
        throw new AppError('APPROVAL_ALREADY_DECIDED', error.message, { status: 409 });
      }
      if (!approval) {
        sendJson(res, 404, { error: { code: 'APPROVAL_NOT_FOUND', message: 'Approval not found.' } });
        return;
      }
      sendJson(res, 200, { approval });
      return;
    }

    if (req.method === 'GET' && pathname === '/api/events') {
      res.writeHead(200, {
        ...SECURITY_HEADERS,
        'Content-Type': 'text/event-stream; charset=utf-8',
        'Cache-Control': 'no-cache, no-transform',
        Connection: 'keep-alive',
        'X-Accel-Buffering': 'no'
      });
      res.write(`retry: 3000\n`);
      res.write(`event: ready\ndata: ${JSON.stringify({ revision: store.snapshot().revision })}\n\n`);
      sseClients.add(res);
      const heartbeat = setInterval(() => {
        res.write(`: heartbeat ${Date.now()}\n\n`);
      }, 20_000);
      heartbeat.unref?.();
      req.on('close', () => {
        clearInterval(heartbeat);
        sseClients.delete(res);
      });
      return;
    }

    sendJson(res, 404, { error: { code: 'NOT_FOUND', message: 'API route not found.' } });
  }

  const server = http.createServer(async (req, res) => {
    const url = new URL(req.url ?? '/', `http://${req.headers.host ?? 'localhost'}`);
    try {
      if (url.pathname.startsWith('/api/')) {
        await handleApi(req, res, url);
      } else {
        serveStatic(req, res, url.pathname, publicDir);
      }
    } catch (error) {
      const payload = toPublicError(error);
      logger.error('http.request_failed', {
        path: url.pathname,
        code: payload.code,
        message: payload.message
      });
      if (res.headersSent) {
        res.destroy();
        return;
      }
      sendJson(res, statusForError(error), { error: payload });
    }
  });

  function listen(port = 0, host = '127.0.0.1') {
    return new Promise((resolve, reject) => {
      server.once('error', reject);
      server.listen(port, host, () => {
        server.off('error', reject);
        resolve({ server, port: server.address().port, host });
      });
    });
  }

  function close() {
    unsubscribe();
    for (const client of sseClients) client.end();
    sseClients.clear();
    return new Promise((resolve) => {
      if (!server.listening) return resolve();
      server.close(() => resolve());
    });
  }

  return { server, store, taskService, bridge, researchProvider, listen, close, publicDir };
}

import { pathToFileURL } from 'node:url';
import { createApp } from './app.js';
import { readConfig } from './config.js';
import { log } from './lib/log.js';

export async function startServer(overrides = {}) {
  const config = readConfig(overrides);
  const app = createApp({
    dataDir: config.dataDir,
    seedPath: config.seedPath,
    publicDir: config.publicDir,
    userAgent: config.userAgent
  });
  const { port, host } = await app.listen(config.port, config.host);
  log.info('server.started', {
    port,
    host,
    seeded: app.store.snapshot().meta.seeded,
    tasks: app.store.snapshot().tasks.length
  });
  return { ...app, port, host, config };
}

const isEntry = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
if (isEntry) {
  const running = await startServer();
  let closing = false;
  const shutdown = async (signal) => {
    if (closing) return;
    closing = true;
    log.info('server.stopping', { signal });
    await running.close();
    process.exit(0);
  };
  process.on('SIGTERM', () => void shutdown('SIGTERM'));
  process.on('SIGINT', () => void shutdown('SIGINT'));
}

:root {
  color-scheme: dark;
  --bg: #08090a;
  --bg-soft: #0c0e0f;
  --panel: #101315;
  --panel-2: #15191b;
  --ink: #ece9e1;
  --muted: #979d99;
  --dim: #66706c;
  --line: #242a2b;
  --line-bright: #39413f;
  --lime: #d8ff43;
  --lime-soft: rgba(216, 255, 67, 0.11);
  --green: #65e6a0;
  --amber: #ffbc57;
  --red: #ff6b5e;
  --blue: #84caff;
  --mono: ui-monospace, "SFMono-Regular", "Cascadia Mono", "Roboto Mono", Menlo, monospace;
  --sans: "Helvetica Neue", "Inter", "Segoe UI", Arial, sans-serif;
  --serif: Georgia, "Times New Roman", serif;
  --topbar: 72px;
  --rail: 252px;
}

* { box-sizing: border-box; }

html {
  background: var(--bg);
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.018) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.018) 1px, transparent 1px);
  background-size: 44px 44px;
  mask-image: linear-gradient(to bottom, black, transparent 82%);
}

.ambient {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background:
    radial-gradient(760px 420px at 82% -8%, rgba(216, 255, 67, 0.085), transparent 65%),
    radial-gradient(600px 380px at 3% 34%, rgba(132, 202, 255, 0.035), transparent 70%);
}

::selection { background: var(--lime); color: #070807; }

a { color: inherit; }
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; }
button:disabled { cursor: wait; opacity: 0.55; }
a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible {
  outline: 2px solid var(--lime);
  outline-offset: 3px;
}
h1, h2, h3, p, dl, dd, ol, ul { margin: 0; }
ul, ol { padding: 0; list-style: none; }

.skip-link {
  position: fixed;
  left: 12px;
  top: -100px;
  z-index: 100;
  padding: 10px 14px;
  background: var(--lime);
  color: #08090a;
  font-family: var(--mono);
  font-size: 11px;
  text-decoration: none;
}
.skip-link:focus { top: 12px; }

/* ---------- shared type ---------- */

.micro-label {
  display: block;
  color: var(--dim);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.17em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.eyebrow-line {
  width: 24px;
  height: 1px;
  background: var(--lime);
}

.slash { color: var(--line-bright); }
.muted { color: var(--muted); }
.locked { color: var(--red) !important; }
.mono { font-family: var(--mono); }

/* ---------- topbar ---------- */

.topbar {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--topbar);
  padding: 0 26px;
  border-bottom: 1px solid var(--line);
  background: rgba(8, 9, 10, 0.88);
  backdrop-filter: blur(16px);
}

.brand-block { display: flex; align-items: center; gap: 12px; min-width: 220px; }
.brand-mark {
  display: grid;
  place-items: center;
  width: 39px;
  height: 39px;
  border: 1px solid var(--line-bright);
  background: var(--ink);
  color: var(--bg);
  font-family: var(--mono);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: -0.13em;
}
.brand-mark span { color: #a4ab1d; }
.brand-name {
  font-family: var(--mono);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.12em;
}
.brand-org {
  color: var(--dim);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.16em;
}

.topbar-center {
  display: flex;
  align-items: baseline;
  gap: 9px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.08em;
}
.topbar-center strong { color: var(--ink); font-weight: 600; }
.topbar-center .micro-label { display: inline; font-size: 8px; }

.topbar-right { display: flex; align-items: center; gap: 22px; }
.bridge-state {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.1em;
}
.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--amber);
  box-shadow: 0 0 0 3px rgba(255, 188, 87, 0.1);
}
.dot.is-online { background: var(--green); box-shadow: 0 0 0 3px rgba(101, 230, 160, 0.1); }
.dot.is-offline { background: var(--red); box-shadow: 0 0 0 3px rgba(255, 107, 94, 0.1); }
.dot-small { width: 5px; height: 5px; background: var(--green); }
.clock { color: var(--dim); font-family: var(--mono); font-size: 9px; letter-spacing: 0.08em; white-space: nowrap; }

/* ---------- shell ---------- */

.app-shell {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: var(--rail) minmax(0, 1fr);
  min-height: calc(100vh - var(--topbar));
}

.rail {
  position: sticky;
  top: var(--topbar);
  display: flex;
  flex-direction: column;
  gap: 28px;
  width: var(--rail);
  height: calc(100vh - var(--topbar));
  padding: 26px 18px 18px;
  border-right: 1px solid var(--line);
  overflow-y: auto;
}

.nav { display: flex; flex-direction: column; gap: 2px; }
.nav-item {
  display: grid;
  grid-template-columns: 24px 1fr auto;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 10px 9px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--muted);
  font-size: 12px;
  text-align: left;
  transition: color 140ms ease, background 140ms ease, border-color 140ms ease;
}
.nav-item:hover { color: var(--ink); background: rgba(255, 255, 255, 0.025); }
.nav-item.is-active {
  border-color: var(--line);
  background: var(--panel);
  color: var(--ink);
}
.nav-item.is-active .nav-index { color: var(--lime); }
.nav-index { color: var(--dim); font-family: var(--mono); font-size: 9px; }
.nav-count {
  min-width: 20px;
  padding: 1px 5px;
  border: 1px solid var(--line);
  color: var(--dim);
  font-family: var(--mono);
  font-size: 9px;
  text-align: center;
}

.agent-panel {
  padding: 15px;
  border: 1px solid var(--line);
  background: linear-gradient(155deg, var(--panel-2), var(--panel));
}
.agent-head { display: flex; align-items: center; gap: 11px; }
.agent-orb {
  display: grid;
  place-items: center;
  width: 39px;
  height: 39px;
  border: 1px solid var(--line-bright);
  background: var(--lime);
  color: #090a06;
  font-family: var(--mono);
  font-size: 17px;
  font-weight: 800;
}
.agent-head h2 { font-size: 17px; letter-spacing: 0.04em; line-height: 1.2; }
.agent-id { color: var(--dim); font-family: var(--mono); font-size: 9px; font-weight: 400; }
.agent-role { margin-top: 9px; color: var(--muted); font-size: 11px; }
.agent-status-line { display: flex; align-items: center; gap: 8px; margin-top: 13px; }
.agent-status-line .muted { font-family: var(--mono); font-size: 8px; }
.agent-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin-top: 14px;
  background: var(--line);
  border: 1px solid var(--line);
}
.agent-stats div { padding: 7px; background: var(--panel); }
.agent-stats dt { color: var(--dim); font-family: var(--mono); font-size: 7px; letter-spacing: 0.08em; text-transform: uppercase; }
.agent-stats dd { margin-top: 2px; font-family: var(--mono); font-size: 15px; }
.agent-task {
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
  color: var(--dim);
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1.5;
}

.guardrails { padding: 0 5px; }
.guardrails ul { margin-top: 10px; display: grid; gap: 5px; }
.guardrails li {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--muted);
  font-size: 10px;
}
.guardrails li::before { content: "×"; color: var(--red); font-family: var(--mono); font-size: 10px; }
.guardrails-note { margin-top: 10px; color: var(--dim); font-size: 9px; line-height: 1.5; }

.rail-foot {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid var(--line);
  color: var(--dim);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.workspace {
  width: 100%;
  max-width: 1500px;
  padding: 38px clamp(22px, 3.8vw, 58px) 80px;
}
.view { animation: view-in 220ms ease both; }
.view[hidden] { display: none; }
@keyframes view-in {
  from { opacity: 0; transform: translateY(5px); }
  to { opacity: 1; transform: none; }
}

/* ---------- hero ---------- */

.hero {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(230px, 0.5fr);
  gap: clamp(28px, 5vw, 80px);
  align-items: end;
  padding: 14px 0 42px;
  border-bottom: 1px solid var(--line);
}
.hero h1 {
  margin-top: 18px;
  font-size: clamp(58px, 7.5vw, 108px);
  font-weight: 700;
  letter-spacing: -0.065em;
  line-height: 0.86;
}
.hero h1 em { color: var(--lime); font-family: var(--serif); font-weight: 400; letter-spacing: -0.045em; }
.lede {
  max-width: 590px;
  margin-top: 23px;
  color: var(--muted);
  font-size: clamp(13px, 1.1vw, 15px);
  line-height: 1.7;
}
.checkpoint {
  max-width: 590px;
  margin-top: 28px;
  padding: 13px 15px;
  border-left: 2px solid var(--red);
  background: rgba(255, 107, 94, 0.035);
}
.checkpoint > div { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.checkpoint strong { font-family: var(--mono); font-size: 12px; letter-spacing: 0.08em; }
.checkpoint p { margin-top: 6px; color: var(--dim); font-size: 9px; line-height: 1.5; }

.hero-aside { display: grid; gap: 12px; }
.hero-signal {
  padding: 19px;
  border: 1px solid var(--line);
  background: linear-gradient(145deg, rgba(216, 255, 67, 0.06), transparent 55%), var(--panel);
}
.hero-signal strong {
  display: block;
  margin-top: 10px;
  color: var(--lime);
  font-family: var(--mono);
  font-size: clamp(17px, 1.7vw, 24px);
  line-height: 1.1;
  letter-spacing: -0.04em;
}
.hero-signal p { margin-top: 10px; color: var(--dim); font-size: 9px; line-height: 1.55; }
.hero-timestamp { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 14px; padding: 13px 2px; border-top: 1px solid var(--line); }
.hero-timestamp p { color: var(--muted); font-family: var(--mono); font-size: 8px; }

/* ---------- buttons / forms ---------- */

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 42px;
  padding: 10px 16px;
  border: 1px solid var(--line-bright);
  background: transparent;
  color: var(--ink);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  text-decoration: none;
  transition: background 140ms ease, color 140ms ease, border-color 140ms ease;
}
.button:hover { border-color: var(--ink); background: rgba(255, 255, 255, 0.04); }
.button-primary { border-color: var(--lime); background: var(--lime); color: #080a03; }
.button-primary:hover { border-color: #e6ff8a; background: #e6ff8a; color: #080a03; }
.button-ghost { border-color: var(--line); color: var(--muted); }
.button-ghost:hover { color: var(--ink); }
.button-small { min-height: 31px; padding: 6px 10px; font-size: 8px; }
.button-danger { border-color: rgba(255, 107, 94, 0.45); color: var(--red); }
.button-danger:hover { background: rgba(255, 107, 94, 0.08); border-color: var(--red); }
.text-button {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}
.text-button:hover { color: var(--lime); }
.icon-button {
  width: 34px;
  height: 34px;
  border: 1px solid var(--line);
  background: transparent;
  color: var(--muted);
  font-size: 20px;
  line-height: 1;
}
.icon-button:hover { color: var(--ink); border-color: var(--line-bright); }

.field { display: flex; flex-direction: column; gap: 7px; }
.field > span {
  color: var(--dim);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
}
.field input, .field select, .search {
  width: 100%;
  height: 43px;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-radius: 0;
  background: #0a0c0d;
  color: var(--ink);
  font-family: var(--mono);
  font-size: 11px;
  outline: none;
  transition: border-color 130ms ease;
}
.field input:hover, .field select:hover, .search:hover { border-color: var(--line-bright); }
.field input:focus, .field select:focus, .search:focus { border-color: var(--lime); }
.field select { appearance: none; background-image: linear-gradient(45deg, transparent 50%, var(--muted) 50%), linear-gradient(135deg, var(--muted) 50%, transparent 50%); background-position: calc(100% - 15px) 19px, calc(100% - 10px) 19px; background-size: 5px 5px, 5px 5px; background-repeat: no-repeat; }
.field-row { display: grid; grid-template-columns: minmax(110px, 0.8fr) minmax(180px, 1.25fr) 82px; gap: 12px; }
.form-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-top: 18px; }
.form-note { margin-top: 12px; color: var(--dim); font-size: 9px; line-height: 1.5; }
.form-error {
  margin-top: 12px;
  padding: 9px 11px;
  border-left: 2px solid var(--red);
  background: rgba(255, 107, 94, 0.06);
  color: #ffaaa3;
  font-family: var(--mono);
  font-size: 9px;
}

/* ---------- panels ---------- */

.panel { border: 1px solid var(--line); background: var(--panel); }
.command-grid { display: grid; grid-template-columns: minmax(0, 1.22fr) minmax(300px, 0.78fr); gap: 14px; margin-top: 14px; }
.assignment-panel { padding: clamp(19px, 2.3vw, 30px); }
.panel-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 18px; }
.panel-head h2 { margin-top: 7px; font-size: clamp(21px, 2vw, 30px); font-weight: 500; letter-spacing: -0.045em; line-height: 1.05; }
.panel-head.compact h2 { font-size: 17px; letter-spacing: -0.025em; }
.panel-head.compact { align-items: center; }
.stamp {
  padding: 5px 7px;
  border: 1px solid rgba(216, 255, 67, 0.3);
  color: var(--lime);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.14em;
  transform: rotate(1.5deg);
}
#research-form { margin-top: 25px; }

.live-panel { display: flex; flex-direction: column; padding: 19px; min-height: 260px; }
.live-body { flex: 1; margin-top: 17px; }
.live-task-title { font-size: 15px; line-height: 1.25; }
.live-task-meta { display: flex; flex-wrap: wrap; gap: 8px 14px; margin-top: 8px; color: var(--dim); font-family: var(--mono); font-size: 8px; }
.live-phase { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-top: 19px; color: var(--muted); font-family: var(--mono); font-size: 9px; }
.live-phase strong { color: var(--lime); font-size: 9px; letter-spacing: 0.08em; }
.progress-track { position: relative; height: 3px; margin-top: 8px; background: var(--line); overflow: hidden; }
.progress-fill { height: 100%; background: var(--lime); transition: width 300ms ease; }
.progress-fill::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.65), transparent);
  animation: scan 1.4s linear infinite;
}
@keyframes scan { from { transform: translateX(-100%); } to { transform: translateX(100%); } }
.live-log { display: grid; gap: 6px; margin-top: 17px; }
.live-log-row { display: grid; grid-template-columns: 44px 1fr; gap: 9px; color: var(--dim); font-family: var(--mono); font-size: 8px; line-height: 1.5; }
.live-log-row time { color: #4f5855; }
.live-log-row span { color: var(--muted); }
.live-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }
.live-error { margin-top: 14px; padding: 10px; border-left: 2px solid var(--red); background: rgba(255, 107, 94, 0.06); }
.live-error strong { color: var(--red); font-family: var(--mono); font-size: 8px; letter-spacing: 0.08em; }
.live-error p { margin-top: 4px; color: #ffaaa3; font-size: 10px; line-height: 1.5; }

/* ---------- metrics ---------- */

.metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  margin-top: 14px;
  border: 1px solid var(--line);
  background: var(--line);
}
.metric { padding: 17px 18px 16px; background: var(--panel); }
.metric strong {
  display: block;
  margin-top: 7px;
  font-family: var(--mono);
  font-size: clamp(28px, 3.2vw, 43px);
  font-weight: 500;
  letter-spacing: -0.08em;
  line-height: 1;
}
.metric p { margin-top: 7px; color: var(--dim); font-size: 8px; line-height: 1.4; }

.overview-columns { display: grid; grid-template-columns: minmax(0, 1.45fr) minmax(280px, 0.55fr); gap: 14px; margin-top: 14px; }
.results-preview, .activity-panel { padding: 19px; }
.results-preview .prospect-stack { margin-top: 15px; }

/* ---------- status ---------- */

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  width: max-content;
  padding: 3px 6px;
  border: 1px solid currentColor;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1.1;
  text-transform: uppercase;
  white-space: nowrap;
}
.status-pill::before { content: ""; width: 4px; height: 4px; border-radius: 50%; background: currentColor; }
.status-idle { color: var(--dim); }
.status-queued { color: var(--blue); }
.status-running { color: var(--lime); }
.status-running::before { animation: pulse 1.1s infinite; }
.status-completed, .status-verified, .status-approved { color: var(--green); }
.status-failed, .status-rejected { color: var(--red); }
.status-awaiting_approval, .status-awaiting, .status-partial { color: var(--amber); }
.status-source_only, .status-unconfirmed { color: var(--dim); }
.status-review { color: var(--amber); }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.25; } }

.priority {
  display: inline-block;
  padding: 3px 5px;
  border: 1px solid var(--line-bright);
  font-family: var(--mono);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.1em;
}
.priority-hot { border-color: rgba(255, 107, 94, 0.5); color: var(--red); }
.priority-warm { border-color: rgba(255, 188, 87, 0.5); color: var(--amber); }
.priority-nurture { border-color: rgba(101, 230, 160, 0.4); color: var(--green); }
.priority-review { border-color: var(--line-bright); color: var(--muted); }

/* ---------- prospect cards ---------- */

.prospect-stack { display: grid; gap: 8px; }
.prospect-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin-top: 22px; }
.prospect-card {
  position: relative;
  border: 1px solid var(--line);
  background: var(--panel);
  overflow: hidden;
}
.prospect-card::before { content: ""; position: absolute; inset: 0 auto 0 0; width: 2px; background: var(--line-bright); }
.prospect-card[data-priority="HOT"]::before { background: var(--red); }
.prospect-card[data-priority="WARM"]::before { background: var(--amber); }
.prospect-card[data-priority="NURTURE"]::before { background: var(--green); }
.prospect-card[data-priority="REVIEW"]::before { background: var(--muted); }
.prospect-card-inner { padding: 18px 18px 16px 20px; }
.prospect-topline { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.prospect-rank { color: var(--dim); font-family: var(--mono); font-size: 8px; letter-spacing: 0.08em; }
.prospect-badges { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; justify-content: flex-end; }
.prospect-name { margin-top: 10px; font-size: 20px; font-weight: 500; letter-spacing: -0.035em; line-height: 1.15; }
.prospect-location { display: flex; gap: 5px; margin-top: 5px; color: var(--dim); font-size: 9px; line-height: 1.4; }
.prospect-location::before { content: "⌖"; color: var(--muted); }
.prospect-site { display: flex; align-items: center; gap: 7px; margin-top: 8px; font-family: var(--mono); font-size: 8px; }
.prospect-site a { color: var(--blue); text-decoration: none; border-bottom: 1px solid rgba(132, 202, 255, 0.25); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.prospect-site a:hover { border-color: var(--blue); }
.prospect-site .site-missing { color: var(--amber); }
.prospect-opportunity { margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--line); }
.prospect-opportunity h4 { font-size: 11px; font-weight: 500; line-height: 1.35; }
.prospect-opportunity p { margin-top: 5px; color: var(--muted); font-size: 9px; line-height: 1.6; }
.prospect-signals { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 9px; }
.signal-chip { padding: 3px 5px; border: 1px solid var(--line); color: var(--dim); font-family: var(--mono); font-size: 7px; }
.prospect-foot { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-top: 13px; padding-top: 11px; border-top: 1px solid var(--line); }
.prospect-counts { display: flex; gap: 12px; color: var(--dim); font-family: var(--mono); font-size: 8px; }
.prospect-counts strong { color: var(--ink); font-weight: 500; }
.prospect-actions { display: flex; gap: 7px; }
.prospect-actions .text-button { font-size: 7px; }
.prospect-stack .prospect-card-inner { padding: 14px 14px 12px 16px; }
.prospect-stack .prospect-name { font-size: 15px; margin-top: 7px; }
.prospect-stack .prospect-location { font-size: 8px; }
.prospect-stack .prospect-opportunity { margin-top: 10px; padding-top: 9px; }
.prospect-stack .prospect-opportunity h4 { font-size: 10px; }
.prospect-stack .prospect-opportunity p { display: none; }

.verify-line { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 10px; }
.check-tag {
  padding: 2px 5px;
  border: 1px solid var(--line);
  color: var(--dim);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.04em;
}
.check-tag.ok { border-color: rgba(101, 230, 160, 0.25); color: rgba(101, 230, 160, 0.8); }
.check-tag.warn { border-color: rgba(255, 188, 87, 0.25); color: rgba(255, 188, 87, 0.9); }

/* ---------- empty ---------- */

.empty-state {
  display: grid;
  justify-items: start;
  gap: 5px;
  padding: 26px 2px;
  color: var(--dim);
}
.empty-state p { color: var(--muted); font-size: 12px; }
.empty-state span:last-child { max-width: 430px; font-size: 9px; line-height: 1.6; }
.empty-glyph { color: var(--line-bright); font-family: var(--mono); font-size: 23px; line-height: 1; }
.compact-empty { padding: 22px 0; }
.wide-empty { grid-column: 1 / -1; padding: 50px 20px; border: 1px dashed var(--line); justify-items: center; text-align: center; }

/* ---------- activity ---------- */

.activity-list { position: relative; display: grid; gap: 0; margin-top: 14px; }
.activity-item { position: relative; display: grid; grid-template-columns: 42px 1fr; gap: 9px; padding: 8px 0 8px 12px; border-left: 1px solid var(--line); }
.activity-item::before { content: ""; position: absolute; left: -3px; top: 14px; width: 5px; height: 5px; border-radius: 50%; background: var(--line-bright); }
.activity-item[data-level="error"]::before { background: var(--red); }
.activity-item[data-level="warn"]::before { background: var(--amber); }
.activity-item time { color: #4d5653; font-family: var(--mono); font-size: 7px; }
.activity-item p { color: var(--muted); font-size: 9px; line-height: 1.45; }
.empty-activity { color: var(--dim); font-family: var(--mono); font-size: 9px; }

/* ---------- view heads ---------- */

.view-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 25px;
  padding: 14px 0 23px;
  border-bottom: 1px solid var(--line);
}
.view-head h1 { margin-top: 12px; font-size: clamp(34px, 4.4vw, 58px); font-weight: 600; letter-spacing: -0.055em; line-height: 0.95; }
.view-lede { max-width: 640px; margin-top: 11px; color: var(--muted); font-size: 12px; line-height: 1.6; }
.view-actions { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.search { width: 220px; height: 37px; font-size: 9px; }
.search::placeholder { color: var(--dim); }

/* ---------- task list ---------- */

.task-list { display: grid; gap: 0; margin-top: 18px; border-top: 1px solid var(--line); }
.task-row {
  display: grid;
  grid-template-columns: minmax(0, 1.6fr) 120px 100px 82px 130px;
  align-items: center;
  gap: 14px;
  padding: 14px 10px;
  border-bottom: 1px solid var(--line);
  transition: background 130ms ease;
}
.task-row:hover { background: rgba(255, 255, 255, 0.018); }
.task-title { min-width: 0; }
.task-title strong { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; font-weight: 500; }
.task-title span { display: block; margin-top: 3px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--dim); font-family: var(--mono); font-size: 7px; }
.task-cell { color: var(--muted); font-family: var(--mono); font-size: 8px; }
.task-cell span { display: block; color: var(--dim); font-size: 7px; margin-bottom: 2px; }
.task-actions { display: flex; justify-content: flex-end; gap: 7px; flex-wrap: wrap; }
.task-progress-mini { width: 100%; height: 2px; margin-top: 6px; background: var(--line); }
.task-progress-mini div { height: 100%; background: var(--lime); }

/* ---------- approvals ---------- */

.approval-banner {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 18px;
  padding: 10px 13px;
  border: 1px solid rgba(255, 188, 87, 0.3);
  background: rgba(255, 188, 87, 0.045);
}
.approval-banner strong { color: var(--amber); font-family: var(--mono); font-size: 8px; letter-spacing: 0.1em; white-space: nowrap; }
.approval-banner span { color: var(--muted); font-size: 9px; }
.approval-list { display: grid; gap: 14px; margin-top: 14px; }
.approval-card { border: 1px solid var(--line); background: var(--panel); padding: 19px; }
.approval-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 15px; }
.approval-top h3 { margin-top: 6px; font-size: 18px; font-weight: 500; letter-spacing: -0.03em; }
.approval-meta { display: flex; gap: 13px; flex-wrap: wrap; margin-top: 5px; color: var(--dim); font-family: var(--mono); font-size: 7px; }
.approval-body { margin-top: 15px; padding: 14px; border: 1px solid var(--line); background: #0b0d0e; }
.approval-subject { color: var(--ink); font-family: var(--mono); font-size: 9px; }
.approval-recipient { margin-top: 5px; color: var(--amber); font-family: var(--mono); font-size: 8px; }
.approval-draft { margin-top: 10px; color: var(--muted); font-family: var(--mono); font-size: 9px; line-height: 1.65; white-space: pre-wrap; }
