/* ---------- evidence ledger ---------- */

.evidence-ledger { display: grid; gap: 22px; margin-top: 22px; }
.evidence-group { border: 1px solid var(--line); background: var(--panel); }
.evidence-group-head { display: flex; align-items: center; justify-content: space-between; gap: 15px; padding: 15px 18px; border-bottom: 1px solid var(--line); }
