.evidence-group-head p { margin-top: 3px; color: var(--dim); font-family: var(--mono); font-size: 8px; }
.evidence-section { padding: 15px 18px; border-bottom: 1px solid var(--line); }
.evidence-section:last-child { border-bottom: 0; }
.evidence-section > h4 { display: flex; align-items: center; gap: 7px; color: var(--muted); font-family: var(--mono); font-size: 8px; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; }
.evidence-section > h4::before { content: "✓"; color: var(--green); }
