.fact a { color: var(--blue); text-decoration: none; border-bottom: 1px solid rgba(132, 202, 255, 0.22); }
.fact a:hover { border-color: var(--blue); }
.fact .fact-id { color: #4c5653; font-family: var(--mono); font-size: 7px; white-space: nowrap; }
.assumption { padding: 10px 0; border-bottom: 1px dashed var(--line); }
.assumption:last-child { border-bottom: 0; }
.assumption p { color: var(--muted); font-size: 10px; line-height: 1.55; }
