/* ---------- dialog ---------- */

.detail-dialog {
  width: min(780px, calc(100vw - 28px));
  max-height: 88vh;
  margin: auto;
  padding: 0;
  border: 1px solid var(--line-bright);
  border-radius: 0;
  background: var(--panel);
  color: var(--ink);
