  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.65);
}
.detail-dialog::backdrop { background: rgba(3, 4, 4, 0.76); backdrop-filter: blur(3px); }
.dialog-topline { position: sticky; top: 0; z-index: 2; display: flex; align-items: center; justify-content: space-between; padding: 13px 17px; border-bottom: 1px solid var(--line); background: var(--panel); }
#detail-content { padding: 22px; }
.dialog-title { margin-top: 9px; font-size: 29px; font-weight: 500; letter-spacing: -0.045em; line-height: 1.05; }
.dialog-sub { margin-top: 7px; color: var(--muted); font-size: 10px; line-height: 1.55; }
.dialog-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 18px; }
.dialog-stat { padding: 11px; border: 1px solid var(--line); background: #0c0e0f; }
.dialog-stat span { display: block; color: var(--dim); font-family: var(--mono); font-size: 7px; letter-spacing: 0.1em; }
.dialog-stat strong { display: block; margin-top: 4px; font-family: var(--mono); font-size: 14px; font-weight: 500; }
.dialog-section { margin-top: 20px; padding-top: 16px; border-top: 1px solid var(--line); }
.dialog-section h3 { font-family: var(--mono); font-size: 9px; letter-spacing: 0.12em; color: var(--muted); text-transform: uppercase; }
.dialog-section p, .dialog-section li { margin-top: 7px; color: var(--muted); font-size: 10px; line-height: 1.6; }
.dialog-section ol { counter-reset: step; }
.dialog-section ol li { padding-left: 22px; position: relative; }
.dialog-section ol li::before { counter-increment: step; content: counter(step, decimal-leading-zero); position: absolute; left: 0; color: var(--lime); font-family: var(--mono); font-size: 7px; }
.dialog-actions { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 20px; }
.raw-list { display: grid; gap: 6px; margin-top: 9px; }
.raw-list div { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; border-bottom: 1px dashed var(--line); color: var(--muted); font-family: var(--mono); font-size: 8px; }
.raw-list strong { color: var(--ink); font-weight: 500; text-align: right; overflow-wrap: anywhere; }

/* ---------- toasts ---------- */

.toast-region { position: fixed; right: 18px; bottom: 18px; z-index: 80; display: grid; gap: 8px; width: min(360px, calc(100vw - 36px)); }
.toast {
  padding: 12px 14px;
  border: 1px solid var(--line-bright);
  border-left: 2px solid var(--green);
  background: #121617;
  color: var(--ink);
  font-family: var(--mono);
  font-size: 9px;
  line-height: 1.5;
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.45);
