}
.toast[data-kind="error"] { border-left-color: var(--red); }
.toast[data-kind="warn"] { border-left-color: var(--amber); }
@keyframes toast-in { from { opacity: 0; transform: translateY(7px); } to { opacity: 1; transform: none; } }

