  const task = latestResearch();
  if (!task) {
    list.appendChild(el('div', { class: 'empty-state wide-empty' }, el('p', { text: 'No evidence recorded yet.' })));
    return;
  }
  const query = ui.searchEvidence.trim().toLowerCase();
