  content.appendChild(el('h2', { class: 'dialog-title', id: 'detail-title', text: task.title }));
  content.appendChild(
    el(
      'div',
      { class: 'view-actions', style: 'margin-top:10px' },
      statusPill(task.status),
      el('span', { class: 'micro-label', text: task.type.replace(/_/g, ' ') }),
