816: function evidenceGroups(task, query = '') {
817:   const groups = [];
818:   for (const prospect of task.results?.prospects ?? []) {
819:     const facts = (prospect.facts ?? []).filter((fact) => {
820:       if (!query) return true;
821:       return `${prospect.name} ${fact.statement} ${fact.source?.url ?? ''} ${fact.method ?? ''}`
822:         .toLowerCase()
823:         .includes(query);
824:     });
825:     const assumptions = (prospect.assumptions ?? []).filter((assumption) => {
826:       if (!query) return true;
827:       return `${prospect.name} ${assumption.statement} ${assumption.rationale ?? ''}`.toLowerCase().includes(query);
828:     });
829:     if (query && !facts.length && !assumptions.length) continue;
830:     groups.push({ prospect, facts, assumptions });
831:   }
832:   return groups;
833: }
