1084: function renderTaskDetail(task) {
1085:   const content = clear($('#detail-content'));
1086:   $('#detail-kicker').textContent = `TASK RECORD · ${task.id}`;
1087:   content.appendChild(el('h2', { class: 'dialog-title', id: 'detail-title', text: task.title }));
1088:   content.appendChild(
1089:     el(
1090:       'div',
1091:       { class: 'view-actions', style: 'margin-top:10px' },
1092:       statusPill(task.status),
1093:       el('span', { class: 'micro-label', text: task.type.replace(/_/g, ' ') }),
1094:       task.delivery?.verified ? el('span', { class: 'status-pill status-verified', text: 'DELIVERY VERIFIED' }) : null
1095:     )
1096:   );
1097:   content.appendChild(
1098:     el('p', {
1099:       class: 'dialog-sub',
1100:       text:
1101:         task.status === 'FAILED'
1102:           ? 'This task failed. No results were delivered and no substitute findings were produced.'
1103:           : task.status === 'AWAITING_APPROVAL'
1104:             ? 'Execution stopped at a human approval gate. Nothing was sent.'
1105:             : 'Execution state, source references and delivery proof are shown below.'
1106:     })
1107:   );
1108: 
1109:   const grid = el('div', { class: 'dialog-grid' });
1110:   const stat = (label, value) =>
1111:     el('div', { class: 'dialog-stat' }, el('span', { text: label }), el('strong', { text: value }));
1112:   grid.appendChild(stat('CREATED', timeText(task.createdAt, 'full')));
1113:   grid.appendChild(stat('STARTED', task.startedAt ? timeText(task.startedAt, 'full') : '—'));
1114:   grid.appendChild(stat('DURATION', task.durationMs != null ? formatDuration(task.durationMs) : '—'));
1115:   grid.appendChild(stat('ATTEMPT', String(task.attempts ?? 1)));
1116:   content.appendChild(grid);
1117: 
